(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,7150,(e,t,s)=>{t.exports=[{slug:"testing-theory",order:1,status:"published",translations:{uk:{title:"Теорія тестування",description:"Фундамент QA: принципи, процес, вимоги, рівні й типи тестування, документація, дефекти, ризики та release readiness."},en:{title:"Testing theory",description:"QA foundations: principles, process, requirements, testing levels and types, documentation, defects, risk, and release readiness."}}},{slug:"test-design",order:2,status:"published",translations:{uk:{title:"Тест-дизайн",description:"Техніки проєктування перевірок, моделювання ризиків і побудова корисного тестового покриття."},en:{title:"Test design",description:"Test design techniques, risk modelling, and building useful test coverage."}}},{slug:"automation-architecture",order:3,status:"published",translations:{uk:{title:"Архітектура автоматизації",description:"Структура тестових фреймворків, межі шарів, підтримуваність і надійні сигнали якості."},en:{title:"Automation architecture",description:"Test framework structure, layer boundaries, maintainability, and reliable quality signals."}}},{slug:"python-coding-whiteboard",order:4,status:"published",translations:{uk:{title:"Python і Coding Whiteboard",description:"Python для QA, алгоритмічне мислення та практичні задачі для технічних співбесід."},en:{title:"Python and Coding Whiteboard",description:"Python for QA, algorithmic thinking, and practical technical interview exercises."}}},{slug:"typescript-playwright-bdd",order:5,status:"published",translations:{uk:{title:"TypeScript, Playwright і BDD",description:"Типобезпечна автоматизація web, патерни Playwright і прагматичне застосування BDD."},en:{title:"TypeScript, Playwright and BDD",description:"Type-safe web automation, Playwright patterns, and pragmatic BDD."}}},{slug:"web-http-networking",order:6,status:"published",translations:{uk:{title:"Web, HTTP і мережі",description:"Як браузер, протоколи та мережеві шари впливають на поведінку й тестованість системи."},en:{title:"Web, HTTP and networking",description:"How browsers, protocols, and network layers affect system behaviour and testability."}}},{slug:"api-sql-data",order:7,status:"published",translations:{uk:{title:"API, SQL і дані",description:"Контракти API, робота з базами даних, цілісність даних і перевірки інтеграцій."},en:{title:"API, SQL and data",description:"API contracts, database work, data integrity, and integration testing."}}},{slug:"cicd-docker-kubernetes",order:8,status:"published",translations:{uk:{title:"CI/CD, Docker і Kubernetes",description:"Пайплайни, контейнери, оркестрація та швидкий зворотний зв’язок від перевірок."},en:{title:"CI/CD, Docker and Kubernetes",description:"Pipelines, containers, orchestration, and fast feedback from quality checks."}}},{slug:"security-devsecops",order:9,status:"published",translations:{uk:{title:"Security і DevSecOps",description:"Моделювання загроз, безпекові перевірки та інтеграція security-практик у delivery."},en:{title:"Security and DevSecOps",description:"Threat modelling, security testing, and integrating security practices into delivery."}}},{slug:"system-design-cloud",order:10,status:"published",translations:{uk:{title:"System Design і Cloud",description:"Компоненти розподілених систем, компроміси архітектури та тестування хмарних рішень."},en:{title:"System Design and Cloud",description:"Distributed system components, architecture trade-offs, and testing cloud solutions."}}},{slug:"ai-llm-rag-agents",order:11,status:"published",translations:{uk:{title:"AI, LLM, RAG і агенти",description:"Будова LLM-рішень, retrieval-архітектури, агенти та їх практичне тестування."},en:{title:"AI, LLM, RAG and agents",description:"LLM solution design, retrieval architectures, agents, and their practical testing."}}},{slug:"llmops-evaluation-observability",order:12,status:"published",translations:{uk:{title:"LLMOps, Evaluation і Observability",description:"Оцінювання якості LLM, експерименти, моніторинг і контроль поведінки AI-систем."},en:{title:"LLMOps, Evaluation and Observability",description:"LLM quality evaluation, experiments, monitoring, and control of AI system behaviour."}}}]},4555,(e,t,s)=>{t.exports=JSON.parse('[{"id":"purpose-of-testing","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що таке тестування програмного забезпечення і навіщо воно потрібне?","answer":"Тестування — це процес статичної та динамічної перевірки продукту й пов’язаних робочих матеріалів для виявлення дефектів і визначення їх відповідності вимогам та потребам користувачів.","examples":["Для сервісу переказів недостатньо побачити успішний платіж: команда також має знати, як система поводиться при повторному запиті, відмові банку та втраті мережі."],"exercises":["Оберіть знайомий продукт і сформулюйте три рішення, для яких результати тестування можуть дати корисну інформацію."]},"en":{"question":"What is software testing, and why do we need it?","answer":"Testing is the process of statically and dynamically examining a product and related work products to identify defects and determine whether they meet requirements and user needs.","examples":["For a money-transfer service, a successful payment is not enough: the team also needs evidence about repeated requests, bank declines, and network loss."],"exercises":["Choose a familiar product and describe three decisions that testing evidence could support."]}}},{"id":"exhaustive-testing","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чому повне, або exhaustive, тестування майже завжди неможливе?","answer":"Кількість комбінацій даних, станів, конфігурацій і шляхів виконання дуже швидко стає практично нескінченною. Тому тестування завжди є вибіркою: ми визначаємо пріоритети за ризиком, застосовуємо техніки тест-дизайну й чесно описуємо, що залишилося неперевіреним.","examples":["Навіть поле з десятьма символами має величезну кількість можливих значень, а разом із браузерами, ролями та станами системи простір перевірок зростає ще більше."],"exercises":["Для форми входу перелічіть виміри тестового простору й поясніть, як скоротите їх без випадкового вибору."]},"en":{"question":"Why is exhaustive testing almost always impossible?","answer":"The number of data combinations, states, configurations, and execution paths quickly becomes impractically large. Testing is therefore a sample: we prioritise by risk, apply test-design techniques, and clearly communicate what remains untested.","examples":["Even a ten-character field allows an enormous number of values; adding browsers, roles, and system states expands the test space further."],"exercises":["For a sign-in form, list the dimensions of the test space and explain how you would reduce them deliberately."]}}},{"id":"qa-qc-testing","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Як пов’язані Quality Assurance, Quality Control і тестування?","answer":"Межі термінів залежать від організації, тому важливіше узгодити відповідальність і очікуваний результат, ніж сперечатися про назви:","answerPoints":["Quality Assurance працює з процесами, які мають запобігати проблемам.","Quality Control оцінює властивості створеного продукту.","Тестування є одним зі способів такого оцінювання."],"examples":["Рев’ю Definition of Done належить до профілактики процесу, а перевірка готового API-контракту — до контролю продукту."],"exercises":["Розподіліть п’ять дій вашої команди між запобіганням дефектам, оцінюванням продукту та тестовим виконанням."]},"en":{"question":"How are Quality Assurance, Quality Control, and testing related?","answer":"Terminology varies by organisation, so agreed responsibilities and outcomes matter more than labels:","answerPoints":["Quality Assurance focuses on processes intended to prevent problems.","Quality Control evaluates properties of the product that was built.","Testing is one way to perform that evaluation."],"examples":["Reviewing the Definition of Done is process prevention, while checking an implemented API contract is product control."],"exercises":["Classify five team activities as defect prevention, product evaluation, or test execution."]}}},{"id":"verification-validation","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чим verification відрізняється від validation?","answer":"Verification перевіряє, чи правильно реалізовано погоджені вимоги, дизайн або контракт. Validation з’ясовує, чи розв’язує продукт реальну потребу користувача. Реалізація може точно відповідати специфікації й водночас бути незручною або непотрібною.","examples":["Форма приймає рівно 20 символів, як вимагає специфікація, але реальні ідентифікатори клієнтів мають 24 символи."],"exercises":["Для checkout наведіть окремий приклад verification і validation та визначте, хто може надати oracle."]},"en":{"question":"How does verification differ from validation?","answer":"Verification checks whether agreed requirements, designs, or contracts were implemented correctly. Validation asks whether the product solves the user’s real need. An implementation can match the specification exactly and still be inconvenient or useless.","examples":["A form accepts exactly 20 characters as specified, but real customer identifiers contain 24 characters."],"exercises":["For a checkout, give one verification and one validation example and identify who can provide the oracle."]}}},{"id":"testing-principles","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Які базові принципи допомагають реалістично планувати тестування?","answer":"Реалістичне планування тестування спирається на такі базові принципи:","answerPoints":["Тестування показує наявність проблем, але не гарантує їх відсутності.","Повна перевірка недосяжна.","Ранній зворотний зв’язок дешевший.","Дефекти часто концентруються в окремих зонах.","Повторення одного набору з часом втрачає ефективність.","Підхід залежить від контексту.","Навіть продукт без відомих дефектів може не задовольняти користувача."],"examples":["Стабільний regression suite роками проходить зелено, але не перевіряє новий мобільний сценарій, яким користується більшість клієнтів."],"exercises":["Оберіть два принципи й опишіть рішення, яке зміниться, якщо команда справді застосує їх у наступному релізі."]},"en":{"question":"Which principles help us plan testing realistically?","answer":"Realistic test planning relies on these core principles:","answerPoints":["Testing can reveal problems but cannot guarantee their absence.","Exhaustive coverage is unattainable.","Earlier feedback is cheaper.","Defects often cluster.","Repeating the same set loses effectiveness over time.","The approach depends on context.","A product with no known defects may still fail its users."],"examples":["A stable regression suite stays green for years but does not cover a new mobile journey used by most customers."],"exercises":["Choose two principles and describe a release decision that would change if the team applied them seriously."]}}},{"id":"test-lifecycle","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"З яких активностей складається життєвий цикл тестування?","answer":"Практичний цикл охоплює аналіз вимог і ризиків, планування, проєктування перевірок, підготовку середовища та даних, виконання, роботу з дефектами, повторні й регресійні перевірки, звітність і завершення. Це не обов’язково лінійні фази: в ітеративній розробці вони перекриваються та повторюються.","examples":["Під час аналізу нового refund workflow команда одночасно уточнює вимоги, готує API fixtures і визначає сигнали для production monitoring."],"exercises":["Намалюйте цикл тестування для невеликої зміни API та позначте входи, результати й відповідальних за кожну активність."]},"en":{"question":"Which activities make up a testing lifecycle?","answer":"A practical lifecycle covers requirement and risk analysis, planning, test design, environment and data preparation, execution, defect work, retesting and regression, reporting, and closure. These are not necessarily linear phases: iterative development makes them overlap and repeat.","examples":["While analysing a new refund workflow, the team also clarifies requirements, prepares API fixtures, and defines production monitoring signals."],"exercises":["Draw the testing lifecycle for a small API change and mark the inputs, outputs, and owners of each activity."]}}},{"id":"requirements-quality","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Які властивості роблять вимогу тестованою та корисною?","answer":"Якісна вимога має бути зрозумілою, однозначною, несуперечливою, повною в потрібних межах, здійсненною, актуальною, пріоритезованою, трасованою й такою, що допускає перевірку. Формальний шаблон не рятує вимогу, якщо команда не може визначити спостережуваний результат.","examples":["«Сторінка має завантажуватися швидко» не дає oracle; «p95 до 2 секунд при 500 активних користувачах у визначеному середовищі» вже можна перевірити."],"exercises":["Візьміть нечітку вимогу й перепишіть її так, щоб з’явилися умови, спостережуваний результат і межі."]},"en":{"question":"What makes a requirement testable and useful?","answer":"A good requirement should be understandable, unambiguous, consistent, sufficiently complete, feasible, current, prioritised, traceable, and verifiable. A formal template does not help when the team cannot identify an observable outcome.","examples":["“The page must load quickly” provides no oracle; “p95 below two seconds for 500 active users in the defined environment” can be tested."],"exercises":["Take a vague requirement and rewrite it with conditions, an observable result, and explicit boundaries."]}}},{"id":"static-dynamic","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чим static testing відрізняється від dynamic testing?","answer":"Static testing аналізує артефакти без виконання програмного коду: вимоги, дизайн, схеми, код або тестові сценарії. Dynamic testing спостерігає поведінку системи під час виконання. Обидва підходи доповнюють один одного й знаходять різні класи проблем.","examples":["Review OpenAPI знаходить суперечливі типи до запуску сервісу, а API test показує фактичну обробку запиту в runtime."],"exercises":["Для нової функції запропонуйте три static і три dynamic перевірки та поясніть очікувані findings."]},"en":{"question":"How does static testing differ from dynamic testing?","answer":"Static testing analyses artefacts without executing application code: requirements, designs, schemas, code, or test scenarios. Dynamic testing observes the running system’s behaviour. The two approaches complement each other and reveal different classes of problems.","examples":["An OpenAPI review finds inconsistent types before the service runs, while an API test shows the actual request handling at runtime."],"exercises":["For a new feature, propose three static and three dynamic checks and explain the findings you expect."]}}},{"id":"black-white-grey-box","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що означають black-box, white-box і grey-box testing?","answer":"Black-box перевірки спираються на зовнішню поведінку без знання реалізації. White-box використовує структуру коду, гілки або внутрішні потоки. Grey-box поєднує зовнішній сценарій з частковим знанням архітектури чи даних. Це способи бачити систему, а не окремі рівні тестування.","examples":["UI-сценарій може бути black-box, unit test гілок розрахунку — white-box, а API-перевірка з контролем запису в базі — grey-box."],"exercises":["Для одного checkout-сценарію спроєктуйте по одній перевірці з кожної перспективи."]},"en":{"question":"What do black-box, white-box, and grey-box testing mean?","answer":"Black-box checks focus on external behaviour without implementation knowledge. White-box testing uses code structure, branches, or internal flows. Grey-box testing combines an external scenario with partial knowledge of architecture or data. These are perspectives on a system, not separate test levels.","examples":["A UI journey may be black-box, a unit test of calculation branches white-box, and an API check with database verification grey-box."],"exercises":["For one checkout scenario, design one check from each perspective."]}}},{"id":"test-levels","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що таке рівні тестування і чим вони відрізняються?","answer":"Рівень тестування визначає масштаб і частину системи, на якій зосереджена перевірка. Межі залежать від архітектури, тому їх потрібно визначати для конкретного продукту:","answerPoints":["Component testing ізолює невелику одиницю.","Integration testing перевіряє взаємодію частин.","System testing розглядає повну систему відносно вимог.","Acceptance testing оцінює готовність задовольнити бізнесову або користувацьку потребу."],"examples":["Функція розрахунку податку, обмін checkout із tax service, повна покупка та бізнесове приймання бухгалтерією — це різні рівні одного ризику."],"exercises":["Розкладіть один критичний ризик вашого продукту на перевірки чотирьох рівнів без дублювання однакових деталей."]},"en":{"question":"What are test levels, and how do they differ?","answer":"A test level defines the scale and part of the system on which a check focuses. Level boundaries depend on architecture and must be defined for the product:","answerPoints":["Component testing isolates a small unit.","Integration testing checks interactions among parts.","System testing evaluates the complete system against requirements.","Acceptance testing assesses readiness to satisfy a business or user need."],"examples":["A tax calculation function, checkout-to-tax-service interaction, a complete purchase, and accounting acceptance represent different levels of one risk."],"exercises":["Map one critical product risk to checks at all four levels without duplicating the same details."]}}},{"id":"test-types","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що таке типи тестування і чим вони відрізняються від рівнів?","answer":"Тип тестування визначає мету перевірки або характеристику якості, яку ми досліджуємо. На відміну від рівня, тип не прив’язаний до конкретного масштабу системи й може застосовуватися на кількох рівнях:","answerPoints":["Functional testing перевіряє, що система робить: правила, обчислення, переходи та результати.","Non-functional testing перевіряє, як система працює: продуктивність, надійність, безпеку, доступність, сумісність та інші характеристики.","White-box, або structural, testing використовує внутрішню структуру системи: statements, branches, paths або data flows.","Change-related testing включає confirmation testing виправленої поведінки та regression testing можливих побічних змін."],"examples":["System — це рівень перевірки повного продукту. На цьому рівні можна виконувати functional, performance, security та regression testing — різні типи тестування."],"exercises":["Для завантаження файлу визначте рівень кожної перевірки та класифікуйте її тип: functional, non-functional, structural або change-related."]},"en":{"question":"What are test types, and how do they differ from test levels?","answer":"A test type defines the objective of a check or the quality characteristic being investigated. Unlike a level, a type is not tied to one scale of the system and can be applied at several levels:","answerPoints":["Functional testing checks what the system does: rules, calculations, transitions, and outcomes.","Non-functional testing checks how the system operates: performance, reliability, security, accessibility, compatibility, and other characteristics.","White-box, or structural, testing uses the system’s internal structure: statements, branches, paths, or data flows.","Change-related testing includes confirmation testing of corrected behaviour and regression testing for unintended side effects."],"examples":["System is the level at which the complete product is checked. Functional, performance, security, and regression testing are different test types that may all be applied at that level."],"exercises":["For file upload checks, identify the level of each check and classify its type as functional, non-functional, structural, or change-related."]}}},{"id":"positive-negative","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що відрізняє positive і negative testing?","answer":"Positive testing перевіряє очікуване використання з допустимими даними. Negative testing досліджує помилкові, неочікувані або заборонені умови й те, чи система безпечно їх обробляє. Negative не означає хаотично вводити «щось неправильне» — сценарій має походити з конкретного ризику.","examples":["Для промокоду positive test використовує активний код у межах правил, а negative — прострочений код, повторне застосування або змінену роль користувача."],"exercises":["Для відновлення пароля створіть три positive і п’ять risk-based negative сценаріїв."]},"en":{"question":"What distinguishes positive and negative testing?","answer":"Positive testing checks expected use with valid data. Negative testing explores invalid, unexpected, or forbidden conditions and whether the system handles them safely. Negative does not mean entering random bad values; each scenario should come from a specific risk.","examples":["For a promo code, a positive test uses an active code within its rules; negative tests cover expiry, reuse, or a changed user role."],"exercises":["Create three positive and five risk-based negative scenarios for password recovery."]}}},{"id":"smoke-sanity-retest-regression","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Як не плутати smoke, sanity, retest і regression?","answer":"Smoke швидко перевіряє, чи збірка придатна для глибшого тестування. Sanity вузько підтверджує узгоджену область після зміни. Retest повторює сценарій конкретного дефекту. Regression шукає небажані наслідки зміни в пов’язаній поведінці. Назви можуть відрізнятися між командами, тому scope має бути явним.","examples":["Після виправлення знижки retest повторює помилковий розрахунок, regression охоплює податок і оплату, а smoke спершу перевіряє, що checkout узагалі відкривається."],"exercises":["Для одного bug fix визначте окремий scope чотирьох наборів і поясніть, які з них можна автоматизувати."]},"en":{"question":"How can we distinguish smoke, sanity, retesting, and regression?","answer":"Smoke testing quickly checks whether a build is suitable for deeper testing. Sanity narrowly confirms an agreed area after a change. Retesting repeats the scenario of a specific defect. Regression looks for unintended effects in related behaviour. Teams use the labels differently, so scope must be explicit.","examples":["After a discount fix, retesting repeats the failed calculation, regression covers tax and payment, while smoke first confirms that checkout opens at all."],"exercises":["For one bug fix, define separate scopes for all four sets and explain which ones should be automated."]}}},{"id":"risk-based-testing","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Як risk-based testing допомагає визначити пріоритет?","answer":"Команда пов’язує глибину й порядок перевірок з імовірністю проблеми та силою її впливу, враховуючи складність зміни, історію дефектів, критичність даних, спостережуваність і вартість відновлення. Це не магічна формула, а прозорий спосіб обговорювати обмеження.","examples":["Невелика зміна формату рахунку може мати високий ризик, якщо документ потрібен для податкової звітності багатьох клієнтів."],"exercises":["Побудуйте risk matrix для трьох змін одного релізу й назвіть сигнал, який змусить переглянути кожну оцінку."]},"en":{"question":"How does risk-based testing help set priorities?","answer":"The team connects testing depth and order to the likelihood and impact of a problem while considering change complexity, defect history, data criticality, observability, and recovery cost. It is not a magic formula but a transparent way to discuss constraints.","examples":["A small invoice-format change may carry high risk when many customers need that document for tax reporting."],"exercises":["Build a risk matrix for three release changes and name one signal that would make you revise each assessment."]}}},{"id":"checklist-vs-test-case","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Коли достатньо checklist, а коли потрібен детальний test case?","answer":"Checklist компактно фіксує ідеї перевірок і добре працює для досвідченої команди та мінливого продукту. Детальний test case корисний, коли потрібні повторюваність, передавання знань, аудит або складні дані й очікування. Формат обирають за ціною неоднозначності, а не за звичкою.","examples":["Короткий список браузерних ризиків може бути checklist, а регульований фінансовий сценарій із точними preconditions і expected results — test case."],"exercises":["Візьміть один сценарій і створіть checklist та test case; порівняйте час підготовки й ризик різного трактування."]},"en":{"question":"When is a checklist enough, and when is a detailed test case needed?","answer":"A checklist compactly captures test ideas and works well for an experienced team and a changing product. A detailed test case helps when repeatability, knowledge transfer, auditability, or complex data and expectations matter. Choose the format by the cost of ambiguity, not habit.","examples":["A short list of browser risks may be a checklist, while a regulated financial flow with exact preconditions and expected results needs a test case."],"exercises":["Represent one scenario as both a checklist and a test case; compare preparation time and interpretation risk."]}}},{"id":"effective-test-case","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Що робить test case справді корисним?","answer":"Корисний test case має зрозумілу мету, контрольовані передумови й дані, однозначні дії, спостережуваний очікуваний результат і зв’язок із ризиком або вимогою. Він має бути достатньо детальним для своєї аудиторії, але не дублювати очевидне й не приховувати oracle у довгому тексті.","examples":["«Перевірити оплату» не пояснює успіх; очікування про статус замовлення, списання, подію та повторний запит роблять перевірку діагностичною."],"exercises":["Відредагуйте слабкий test case: приберіть зайві UI-деталі, додайте дані, oracle та postconditions."]},"en":{"question":"What makes a test case genuinely useful?","answer":"A useful test case has a clear purpose, controlled preconditions and data, unambiguous actions, an observable expected result, and a link to a risk or requirement. It should be detailed enough for its audience without restating the obvious or hiding the oracle in long prose.","examples":["“Test payment” does not define success; expectations for order state, charge, event, and retry behaviour make the check diagnostic."],"exercises":["Edit a weak test case: remove incidental UI detail and add data, an oracle, and postconditions."]}}},{"id":"defect-failure-root-cause","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Чим відрізняються error, defect, failure і root cause?","answer":"Один failure може мати кілька причин, а defect може довго не проявлятися. Терміни означають:","answerPoints":["Error — людська помилка або неправильне рішення.","Defect — вада в артефакті чи коді.","Failure — спостережуване відхилення системи під час виконання.","Root cause — глибинна причина, що дозволила проблемі виникнути або пройти далі."],"examples":["Неправильно зрозуміле правило призвело до дефектної умови в коді; failure видно лише для певної валюти, а root cause включає нечітку вимогу й відсутнє review."],"exercises":["Для відомого production incident побудуйте ланцюг error → defect → failure → contributing causes."]},"en":{"question":"How do error, defect, failure, and root cause differ?","answer":"One failure may have several causes, and a defect may remain dormant. The terms mean:","answerPoints":["An error is a human mistake or incorrect decision.","A defect is a flaw in an artefact or code.","A failure is an observable deviation while the system runs.","A root cause is an underlying condition that allowed the problem to occur or escape."],"examples":["A misunderstood rule produced a faulty condition in code; the failure appears only for one currency, while root causes include a vague requirement and missing review."],"exercises":["For a known production incident, map error → defect → failure → contributing causes."]}}},{"id":"defect-report","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Які дані потрібні в якісному defect report?","answer":"Звіт має дозволити зрозуміти, відтворити й оцінити проблему: короткий фактичний заголовок, версія та середовище, передумови й дані, мінімальні кроки, actual і expected result, стабільність відтворення, вплив, докази та пов’язані артефакти. Severity описує наслідок, priority — терміновість рішення.","examples":["Замість «оплата не працює» корисний заголовок називає умову, місце й результат: «Повторний POST створює друге списання після timeout відповіді»."],"exercises":["Перепишіть нечіткий bug report так, щоб інша людина могла відтворити проблему без усного пояснення."]},"en":{"question":"What information belongs in a good defect report?","answer":"A report should let others understand, reproduce, and assess the problem: a factual summary, version and environment, preconditions and data, minimal steps, actual and expected results, reproducibility, impact, evidence, and related artefacts. Severity describes impact; priority describes urgency.","examples":["Instead of “payment is broken,” a useful summary names condition, location, and outcome: “Repeated POST creates a second charge after response timeout.”"],"exercises":["Rewrite a vague bug report so another person can reproduce the problem without verbal context."]}}},{"id":"severity-priority","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Чому severity і priority не можна зводити до одного поля?","answer":"Severity оцінює масштаб і характер впливу дефекту на продукт, користувача або дані. Priority відображає бізнесову черговість виправлення з урахуванням дедлайнів, охоплення, workaround і вартості. Висока severity не завжди означає перше виправлення, а низька severity може мати терміновий бізнесовий контекст.","examples":["Рідкісний crash адміністративного інструмента може мати високу severity, але нижчий priority; помилка в тексті на головній сторінці перед кампанією — навпаки."],"exercises":["Наведіть чотири комбінації high/low severity та priority і обґрунтуйте їх контекстом."]},"en":{"question":"Why should severity and priority remain separate?","answer":"Severity estimates the scale and nature of a defect’s impact on the product, user, or data. Priority represents business repair order considering deadlines, reach, workarounds, and cost. High severity does not always mean first to fix, while a low-severity issue can be urgent in its business context.","examples":["A rare crash in an admin tool may have high severity but lower priority; a homepage typo before a campaign can show the opposite pattern."],"exercises":["Provide four high/low severity and priority combinations and justify each with context."]}}},{"id":"test-basis-oracle","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що таке test basis і test oracle?","answer":"Test basis — це джерела, з яких ми виводимо умови перевірки: вимоги, контракти, моделі, ризики, закони або фактичну поведінку попередньої версії. Test oracle — спосіб визначити очікуваний результат. Oracle може походити зі специфікації, бізнес-правила, еталонної системи, обчислення чи думки експерта, але його надійність теж потрібно оцінювати.","examples":["Для розрахунку знижки test basis містить правила програми лояльності, а oracle може бути незалежним розрахунком очікуваної суми."],"exercises":["Для знайомої функції перелічіть доступні test basis, оберіть oracle і вкажіть, де він може помилятися."]},"en":{"question":"What are a test basis and a test oracle?","answer":"A test basis is the set of sources from which we derive test conditions: requirements, contracts, models, risks, laws, or the observed behaviour of an earlier version. A test oracle is the means used to determine the expected result. It may come from a specification, business rule, reference system, calculation, or expert judgement, and its reliability must also be assessed.","examples":["For a discount calculation, the loyalty-program rules form the test basis, while an independent calculation can serve as the oracle."],"exercises":["For a familiar feature, list the available test basis, choose an oracle, and identify how that oracle could be wrong."]}}},{"id":"traceability-coverage","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Навіщо потрібна трасованість між вимогами, ризиками та перевірками?","answer":"Трасованість показує, які вимоги й ризики покриті перевірками, які результати та дефекти з ними пов’язані, а де залишилися прогалини. Це не обов’язково велика RTM-таблиця: зв’язки можуть жити в test management, issue tracker або коді. Важлива можливість відповісти, що саме перевірено і яким evidence це підтверджено.","examples":["Посилання requirement → API test → запуск CI → defect дозволяє побачити не лише наявність тесту, а й актуальний результат та відому проблему."],"exercises":["Побудуйте мінімальну traceability map для трьох вимог і перевірте, чи є вимога без тесту або тест без зрозумілої мети."]},"en":{"question":"Why do we need traceability between requirements, risks, and tests?","answer":"Traceability shows which requirements and risks are covered by checks, which results and defects relate to them, and where gaps remain. It does not have to be a large RTM spreadsheet: links may live in test management, an issue tracker, or code. What matters is being able to explain what was checked and which evidence supports it.","examples":["A requirement → API test → CI run → defect chain shows not only that a test exists, but also its current result and a known problem."],"exercises":["Build a minimal traceability map for three requirements and look for a requirement without a test or a test without a clear purpose."]}}},{"id":"test-environment-data","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Чому тестове середовище й дані є частиною дизайну перевірок?","answer":"Результат залежить не лише від кроків тесту, а й від версій сервісів, конфігурації, інтеграцій, доступів, часу та стану даних. Контрольоване середовище підвищує відтворюваність, а репрезентативні дані допомагають побачити реальні ризики. Водночас тестові дані мають відповідати правилам приватності й безпеки.","examples":["Refund test може проходити на stub, але падати зі справжнім payment sandbox через інший timeout і повторну доставку webhook."],"exercises":["Для одного integration test складіть перелік залежностей, конфігурацій і даних, які потрібно контролювати або фіксувати в evidence."]},"en":{"question":"Why are test environments and data part of test design?","answer":"A result depends not only on test steps but also on service versions, configuration, integrations, access, time, and data state. A controlled environment improves reproducibility, while representative data helps expose realistic risks. Test data must also comply with privacy and security rules.","examples":["A refund test may pass against a stub but fail with the real payment sandbox because of a different timeout and webhook redelivery."],"exercises":["For one integration test, list the dependencies, configurations, and data that must be controlled or recorded as evidence."]}}},{"id":"entry-exit-criteria","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Що дають entry, exit і suspension criteria?","answer":"Ці критерії є орієнтирами для рішення, а не автоматичною гарантією якості:","answerPoints":["Entry criteria визначають, коли тестову активність має сенс починати.","Exit criteria визначають, який evidence потрібен для завершення активності або рішення.","Suspension criteria визначають, коли продовження не дає надійного результату чи марнує ресурс."],"examples":["Якщо середовище нестабільне й половина API-запитів падає через інфраструктуру, suspension criterion захищає команду від фальшивих висновків."],"exercises":["Сформулюйте entry, exit і suspension criteria для короткого regression cycle та додайте відповідального за винятки."]},"en":{"question":"What do entry, exit, and suspension criteria provide?","answer":"These criteria guide decisions rather than automatically guaranteeing quality:","answerPoints":["Entry criteria define when a test activity is ready to start.","Exit criteria define the evidence needed to finish it or make a decision.","Suspension criteria define when continuing would produce unreliable results or waste resources."],"examples":["If the environment is unstable and half of the API requests fail because of infrastructure, a suspension criterion prevents the team from drawing false conclusions."],"exercises":["Define entry, exit, and suspension criteria for a short regression cycle and name the owner of exceptions."]}}},{"id":"defect-lifecycle","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Що описує життєвий цикл дефекту?","answer":"Життєвий цикл дефекту описує стани й рішення від реєстрації до закриття: triage, призначення, виправлення, перевірку, повторне відкриття, відкладення або відхилення. Конкретні назви залежать від команди. Важливі чіткі переходи, відповідальність і причина рішення, а не максимальна кількість статусів.","examples":["Після статусу Fixed перевірка підтверджує початковий сценарій, але regression знаходить побічний ефект: це може бути reopen або окремий defect за правилами команди."],"exercises":["Намалюйте мінімальний defect workflow для своєї команди й визначте, хто та на основі якого evidence виконує кожен перехід."]},"en":{"question":"What does a defect lifecycle describe?","answer":"A defect lifecycle describes states and decisions from reporting to closure: triage, assignment, fixing, verification, reopening, deferral, or rejection. Exact labels vary by team. Clear transitions, ownership, and reasons for decisions matter more than having many statuses.","examples":["After a defect is marked Fixed, verification confirms the original scenario but regression reveals a side effect; team policy determines whether to reopen it or report a separate defect."],"exercises":["Draw a minimal defect workflow for your team and define who performs each transition and which evidence supports it."]}}},{"id":"test-strategy","direction":"testing-theory","level":"Senior","translations":{"uk":{"question":"Що має пояснювати test strategy?","answer":"Стратегія пов’язує цілі якості й продуктові ризики з рівнями, типами та техніками тестування. Вона визначає scope і виключення, середовища, дані, automation approach, ролі, evidence, критерії входу й виходу, звітність та реакцію на findings. Це модель рішень, а не шаблон документа заради документа.","examples":["Для платіжної функції стратегія може перенести більшість контрактних перевірок на API-рівень, залишити кілька критичних UI journeys і додати production signals."],"exercises":["Створіть односторінкову стратегію для зміни з трьома головними ризиками та поясніть, що свідомо не тестуватимете."]},"en":{"question":"What should a test strategy explain?","answer":"A strategy connects quality goals and product risks to testing levels, types, and techniques. It defines scope and exclusions, environments, data, automation approach, roles, evidence, entry and exit criteria, reporting, and responses to findings. It is a decision model, not a document template for its own sake.","examples":["For a payment feature, the strategy may place most contract checks at API level, retain a few critical UI journeys, and add production signals."],"exercises":["Create a one-page strategy for a change with three major risks and explain what you will deliberately not test."]}}},{"id":"release-readiness","direction":"testing-theory","level":"Senior","translations":{"uk":{"question":"Як оцінювати release readiness без магічного відсотка pass rate?","answer":"Готовність до релізу — це рішення на основі evidence: покриття критичних ризиків, стан важливих дефектів, результати перевірок і review, стабільність середовища, якість даних, відомі обмеження, observability, rollback і відповідальність за прийняття ризику. Pass rate корисний лише разом із контекстом набору.","examples":["99% green може приховувати єдиний провалений сценарій повернення коштів, тоді як 90% із падіннями неактуальних low-risk тестів може не блокувати реліз."],"exercises":["Підготуйте короткий release recommendation із фактами, невизначеністю, залишковими ризиками та явним decision owner."]},"en":{"question":"How can release readiness be assessed without a magic pass-rate threshold?","answer":"Release readiness is a decision based on evidence: coverage of critical risks, important defect status, test and review outcomes, environment stability, data quality, known limitations, observability, rollback, and ownership of risk acceptance. Pass rate is useful only with the context of the test set.","examples":["A 99% green result may hide the one failed refund journey, while 90% with obsolete low-risk failures may not block release."],"exercises":["Prepare a short release recommendation containing facts, uncertainty, residual risks, and an explicit decision owner."]}}},{"id":"metrics-context","direction":"testing-theory","level":"Senior","translations":{"uk":{"question":"Які тестові метрики допомагають, а які вводять в оману?","answer":"Метрика корисна, коли підтримує конкретне рішення й має зрозумілий знаменник та контекст. Тренд escaped defects, час зворотного зв’язку або покриття визначених ризиків можуть показати проблему. Кількість test cases, знайдених дефектів чи automation percentage без контексту легко перетворюються на vanity metrics і стимулюють неправильну поведінку.","examples":["Зростання кількості тестів нічого не доводить, якщо suite триває довше, частіше flaky й не знаходить критичних regressions."],"exercises":["Оберіть три метрики вашої команди й для кожної запишіть рішення, обмеження та можливий спосіб маніпуляції."]},"en":{"question":"Which testing metrics help, and which mislead?","answer":"A metric is useful when it supports a specific decision and has a clear denominator and context. Trends in escaped defects, feedback time, or coverage of defined risks may expose a problem. Counts of test cases, defects, or automation percentage without context easily become vanity metrics and encourage harmful behaviour.","examples":["A growing test count proves little when the suite becomes slower, flakier, and still misses critical regressions."],"exercises":["Choose three team metrics and document the decision, limitation, and possible gaming behaviour for each."]}}}]')},2400,(e,t,s)=>{t.exports=JSON.parse('[{"id":"equivalence-partitioning","direction":"test-design","level":"Junior","translations":{"uk":{"question":"Навіщо equivalence partitioning?","answer":"Ділить вхідні дані на класи з очікувано однаковою поведінкою, щоб зменшити кількість перевірок.","examples":["Поле віку 18–65 можна перевірити представниками валідного класу та класів нижче і вище меж."],"exercises":["Для правила кількості 1–99 визнач класи еквівалентності й вибери представників."]},"en":{"question":"Why use equivalence partitioning?","answer":"It divides input data into classes expected to behave alike, reducing the number of checks.","examples":["For an age field accepting 18–65, test representatives of the valid class and the classes below and above the limits."],"exercises":["For a quantity rule of 1–99, identify equivalence classes and choose representatives."]}}},{"id":"decision-table","direction":"test-design","level":"Middle","translations":{"uk":{"question":"Коли потрібна decision table?","answer":"Коли результат залежить від комбінацій умов і бізнес-правил.","examples":["Знижка може залежати одночасно від ролі користувача, суми замовлення та промокоду."],"exercises":["Побудуй decision table для знижки за роллю, сумою та наявністю промокоду."]},"en":{"question":"When is a decision table useful?","answer":"When an outcome depends on combinations of conditions and business rules.","examples":["A discount may depend on the user role, order total, and promo code at the same time."],"exercises":["Build a decision table for a discount based on role, total, and promo code."]}}},{"id":"pairwise-limits","direction":"test-design","level":"Senior","translations":{"uk":{"question":"Чи гарантує pairwise відсутність дефектів?","answer":"Ні. Він покриває пари значень факторів, але може пропустити взаємодії трьох і більше факторів.","examples":["Помилка може виникати лише для Safari, гостьового користувача та конкретної валюти разом."],"exercises":["Візьми чотири фактори checkout і поясни, який ризик залишиться після pairwise-набору."]},"en":{"question":"Does pairwise testing guarantee an absence of defects?","answer":"No. It covers pairs of factor values but may miss interactions among three or more factors.","examples":["A defect may occur only for Safari, a guest user, and one currency together."],"exercises":["Take four checkout factors and explain which risk remains after a pairwise set."]}}},{"id":"automation-priority","direction":"automation-architecture","level":"Junior","translations":{"uk":{"question":"Що автоматизувати першочергово?","answer":"Стабільні, повторювані й ризикові сценарії з надійним oracle та прийнятною вартістю підтримки.","examples":["Критичний checkout із чітким API-результатом зазвичай кращий кандидат, ніж мінливий візуальний прототип."],"exercises":["Порівняй два сценарії за ризиком, повторюваністю, oracle і вартістю підтримки."]},"en":{"question":"What should be automated first?","answer":"Stable, repeatable, high-risk scenarios with a reliable oracle and acceptable maintenance cost.","examples":["A critical checkout with a clear API outcome is usually a better candidate than a changing visual prototype."],"exercises":["Compare two scenarios by risk, repeatability, oracle quality, and maintenance cost."]}}},{"id":"flaky-test","direction":"automation-architecture","level":"Middle","translations":{"uk":{"question":"Що таке flaky test?","answer":"Це тест із нестабільним результатом за суттєво однакових умов; причина може бути в тесті, середовищі або продукті.","examples":["Тест іноді падає через гонку запитів, хоча код і тестові дані не змінювалися."],"exercises":["Для нестабільного тесту склади план збору evidence до додавання retry."]},"en":{"question":"What is a flaky test?","answer":"A test with unstable outcomes under materially identical conditions; the cause may be in the test, environment, or product.","examples":["A test sometimes fails because of a request race even though code and test data did not change."],"exercises":["For an unstable test, plan the evidence to collect before adding a retry."]}}},{"id":"automation-layers","direction":"automation-architecture","level":"Senior","translations":{"uk":{"question":"Навіщо розділяти test logic і client/page layers?","answer":"Щоб сценарії описували поведінку, а деталі протоколів та UI змінювалися локально.","examples":["Зміна API endpoint має вимагати правки клієнта, а не кожного бізнес-сценарію."],"exercises":["Спроєктуй checkout: API setup → UI action → API assertion → cleanup і познач межі шарів."]},"en":{"question":"Why separate test logic from client and page layers?","answer":"So scenarios describe behaviour while protocol and UI details change locally.","examples":["An API endpoint change should require updating the client, not every business scenario."],"exercises":["Design a checkout flow—API setup, UI action, API assertion, cleanup—and mark the layer boundaries."]}}},{"id":"mutable-default","direction":"python-coding-whiteboard","level":"Junior","translations":{"uk":{"question":"Чому mutable default argument небезпечний?","answer":"Default-об’єкт створюється під час визначення функції та повторно використовується між викликами.","examples":["Список за замовчуванням може зберегти елемент із попереднього виклику функції."],"exercises":["Напиши мінімальний приклад помилки й виправ його через значення None."]},"en":{"question":"Why is a mutable default argument dangerous?","answer":"The default object is created when the function is defined and reused across calls.","examples":["A default list may retain an item from a previous function call."],"exercises":["Write a minimal failing example and fix it by using None."]}}},{"id":"generator-vs-list","direction":"python-coding-whiteboard","level":"Middle","translations":{"uk":{"question":"Чим generator відрізняється від list?","answer":"Generator видає значення поступово; list зберігає всі елементи. Generator зазвичай одноразовий і не підтримує довільний індексний доступ.","examples":["Потік великого файлу можна обробляти генератором без завантаження всіх рядків у пам’ять."],"exercises":["Реалізуй генератор читання даних пакетами й порівняй використання пам’яті зі списком."]},"en":{"question":"How does a generator differ from a list?","answer":"A generator yields values gradually; a list stores every item. A generator is usually single-use and has no arbitrary index access.","examples":["A large file can be streamed with a generator without loading every row into memory."],"exercises":["Implement batched data reading as a generator and compare memory use with a list."]}}},{"id":"asyncio-cpu","direction":"python-coding-whiteboard","level":"Senior","translations":{"uk":{"question":"Чи прискорює asyncio CPU-heavy код?","answer":"Сам по собі — ні. Він корисний для конкурентного очікування I/O; CPU-heavy роботу слід планувати окремо.","examples":["Паралельне очікування HTTP-відповідей виграє від asyncio, а важке обчислення хешів блокує event loop."],"exercises":["Класифікуй п’ять задач як I/O-bound або CPU-bound і запропонуй модель виконання."]},"en":{"question":"Does asyncio speed up CPU-heavy code?","answer":"Not by itself. It helps with concurrent I/O waiting; CPU-heavy work needs a different execution strategy.","examples":["Waiting for HTTP responses can benefit from asyncio, while heavy hash calculation blocks the event loop."],"exercises":["Classify five tasks as I/O-bound or CPU-bound and propose an execution model."]}}},{"id":"isolated-browser-context","direction":"typescript-playwright-bdd","level":"Middle","translations":{"uk":{"question":"Навіщо ізольований browser context?","answer":"Він розділяє cookies і browser state між тестами; backend-дані потрібно ізолювати окремо.","examples":["Два тести можуть мати окремі сесії браузера, але конфліктувати через спільний запис користувача в базі."],"exercises":["Запусти два сценарії паралельно та познач browser і backend state, які треба ізолювати."]},"en":{"question":"Why use an isolated browser context?","answer":"It separates cookies and browser state between tests; backend data must be isolated separately.","examples":["Two tests may have separate browser sessions but still collide on one user record in the database."],"exercises":["Run two scenarios in parallel and identify browser and backend state that must be isolated."]}}},{"id":"await-promises","direction":"typescript-playwright-bdd","level":"Junior","translations":{"uk":{"question":"Чому await важливий?","answer":"Без очікування Promise наступна дія може початися до завершення попередньої, а помилка — залишитися поза потрібним обробником.","examples":["Клік без await може перетнутися з перевіркою навігації та створити гонку."],"exercises":["Знайди пропущений await у короткому тесті й поясни можливий порядок подій."]},"en":{"question":"Why is await important?","answer":"Without awaiting a Promise, the next action may start before the previous one finishes and an error may escape the intended handler.","examples":["A click without await may race with a navigation assertion."],"exercises":["Find a missing await in a short test and explain the possible event order."]}}},{"id":"gherkin-scope","direction":"typescript-playwright-bdd","level":"Senior","translations":{"uk":{"question":"Що має описувати Gherkin?","answer":"Спостережувану бізнес-поведінку й очікуваний результат; дрібні технічні дії краще ховати в реалізації steps.","examples":["Крок «клієнт завершує оплату» стабільніший за перелік кожного CSS-селектора й кліку."],"exercises":["Опиши checkout у Gherkin і винеси API setup та технічні деталі в reusable steps."]},"en":{"question":"What should Gherkin describe?","answer":"Observable business behaviour and the expected outcome; small technical actions belong in step implementations.","examples":["A step such as “the customer completes payment” is more stable than listing every CSS selector and click."],"exercises":["Describe checkout in Gherkin and move API setup and technical details into reusable steps."]}}},{"id":"idempotent-method","direction":"web-http-networking","level":"Middle","translations":{"uk":{"question":"Що означає idempotent method?","answer":"Кілька однакових запитів мають той самий очікуваний ефект на стан сервера, що й один. Відповіді можуть відрізнятися.","examples":["Повторний PUT того самого стану не створює ще один ресурс, хоча timestamp у відповіді може змінитися."],"exercises":["Перевір повторення PUT і сформулюй окремо очікування до стану та відповіді."]},"en":{"question":"What does an idempotent method mean?","answer":"Several identical requests have the same expected effect on server state as one request. Responses may differ.","examples":["Repeating a PUT for the same state does not create another resource, although a response timestamp may change."],"exercises":["Repeat a PUT and define separate expectations for state and response."]}}},{"id":"http-401-403","direction":"web-http-networking","level":"Junior","translations":{"uk":{"question":"Чим 401 відрізняється від 403?","answer":"401 означає відсутність придатних authentication credentials; 403 — сервер зрозумів запит, але відмовляє в доступі.","examples":["Запит без токена отримує 401, а автентифікований користувач без потрібної ролі — 403."],"exercises":["Склади негативні API-перевірки для відсутнього, невалідного й недостатньо привілейованого токена."]},"en":{"question":"How does 401 differ from 403?","answer":"401 means suitable authentication credentials are missing; 403 means the server understood the request but refuses access.","examples":["A request without a token gets 401, while an authenticated user lacking the required role gets 403."],"exercises":["Design negative API checks for missing, invalid, and insufficiently privileged tokens."]}}},{"id":"cors","direction":"web-http-networking","level":"Senior","translations":{"uk":{"question":"Що робить CORS?","answer":"Керує дозволом браузеру читати cross-origin responses; це не заміна серверної авторизації.","examples":["curl може прочитати відповідь, яку браузерний JavaScript блокує через CORS."],"exercises":["Порівняй той самий cross-origin запит у браузері та curl і досліди preflight."]},"en":{"question":"What does CORS do?","answer":"It controls whether a browser may read cross-origin responses; it does not replace server-side authorization.","examples":["curl may read a response that browser JavaScript blocks because of CORS."],"exercises":["Compare the same cross-origin request in a browser and curl, and inspect the preflight."]}}},{"id":"database-transaction","direction":"api-sql-data","level":"Middle","translations":{"uk":{"question":"Навіщо транзакція?","answer":"Щоб пов’язані операції завершилися як одна логічна одиниця з commit або rollback.","examples":["Створення замовлення й резервування залишку мають або завершитися разом, або разом відкотитися."],"exercises":["Змоделюй помилку між двома SQL-операціями й перевір rollback."]},"en":{"question":"Why use a transaction?","answer":"So related operations complete as one logical unit with either commit or rollback.","examples":["Creating an order and reserving stock should either both complete or both roll back."],"exercises":["Simulate a failure between two SQL operations and verify the rollback."]}}},{"id":"database-index","direction":"api-sql-data","level":"Senior","translations":{"uk":{"question":"Чому index не завжди прискорює систему?","answer":"Він може пришвидшити читання, але коштує місця та роботи під час запису; користь залежить від query plan і розподілу даних.","examples":["Індекс на низькоселективному полі може не використовуватися, але все одно сповільнювати вставки."],"exercises":["Порівняй EXPLAIN до й після індексу та виміряй вплив на читання і запис."]},"en":{"question":"Why does an index not always make a system faster?","answer":"It may speed up reads but costs storage and work on writes; value depends on the query plan and data distribution.","examples":["An index on a low-selectivity field may be ignored while still slowing inserts."],"exercises":["Compare EXPLAIN before and after an index, and measure its effect on reads and writes."]}}},{"id":"api-beyond-status","direction":"api-sql-data","level":"Junior","translations":{"uk":{"question":"Що перевіряти крім HTTP status?","answer":"Схему й семантику response, зміни стану, авторизацію, побічні ефекти та поведінку повторного запиту.","examples":["201 не гарантує, що ресурс збережений правильно або подія була опублікована рівно один раз."],"exercises":["Для create endpoint склади перевірки контракту, стану, прав доступу, side effects та повтору."]},"en":{"question":"What should be checked beyond the HTTP status?","answer":"Response schema and semantics, state changes, authorization, side effects, and repeated-request behaviour.","examples":["A 201 does not prove that the resource was stored correctly or that an event was published exactly once."],"exercises":["For a create endpoint, design checks for contract, state, access, side effects, and retries."]}}},{"id":"continuous-delivery-deployment","direction":"cicd-docker-kubernetes","level":"Junior","translations":{"uk":{"question":"Чим continuous delivery відрізняється від deployment?","answer":"Delivery підтримує готовність змін до випуску; deployment автоматично доставляє придатні зміни в production.","examples":["У delivery реліз може вимагати ручного рішення, тоді як deployment випускає успішну зміну автоматично."],"exercises":["Намалюй pipeline для обох моделей і познач місце людського approval."]},"en":{"question":"How does continuous delivery differ from continuous deployment?","answer":"Delivery keeps changes ready for release; deployment automatically releases suitable changes to production.","examples":["With delivery, release may require a human decision; deployment releases a successful change automatically."],"exercises":["Draw a pipeline for both models and mark the human approval point."]}}},{"id":"image-vs-container","direction":"cicd-docker-kubernetes","level":"Middle","translations":{"uk":{"question":"Чим image відрізняється від container?","answer":"Image — шаблон файлової системи й конфігурації; container — його запущений або зупинений екземпляр із власним станом.","examples":["З одного immutable image можна запустити кілька контейнерів із різними змінними середовища."],"exercises":["Збери image, запусти два контейнери й порівняй їхню конфігурацію та writable state."]},"en":{"question":"How does an image differ from a container?","answer":"An image is a filesystem and configuration template; a container is its running or stopped instance with its own state.","examples":["One immutable image can start multiple containers with different environment variables."],"exercises":["Build an image, run two containers, and compare their configuration and writable state."]}}},{"id":"readiness-liveness","direction":"cicd-docker-kubernetes","level":"Senior","translations":{"uk":{"question":"Чим readiness відрізняється від liveness?","answer":"Readiness визначає готовність приймати трафік; liveness — чи слід перезапустити контейнер через непрацездатність.","examples":["Під час warm-up pod може бути живим, але ще не готовим отримувати запити."],"exercises":["Спроєктуй окремі probes для сервісу, що довго прогріває cache."]},"en":{"question":"How does readiness differ from liveness?","answer":"Readiness decides whether a workload can receive traffic; liveness decides whether it should be restarted as unhealthy.","examples":["During warm-up, a pod may be alive but not ready to receive requests."],"exercises":["Design separate probes for a service with a long cache warm-up."]}}},{"id":"authentication-authorization","direction":"security-devsecops","level":"Junior","translations":{"uk":{"question":"Чим authentication відрізняється від authorization?","answer":"Authentication встановлює, хто виконує дію; authorization визначає, чи дозволена йому конкретна дія над ресурсом.","examples":["Валідний користувач може увійти в систему, але не мати права читати чуже замовлення."],"exercises":["Негативно перевір доступ до чужого order у навчальному локальному середовищі."]},"en":{"question":"How does authentication differ from authorization?","answer":"Authentication establishes who performs an action; authorization decides whether that identity may act on a resource.","examples":["A valid user may sign in but still lack permission to read another user’s order."],"exercises":["Negatively test access to another user’s order in a local training environment."]}}},{"id":"sast-dast","direction":"security-devsecops","level":"Middle","translations":{"uk":{"question":"Чому SAST і DAST доповнюють одне одного?","answer":"SAST аналізує код без запуску; DAST перевіряє поведінку запущеної системи. Обидва мають прогалини й false positives.","examples":["SAST бачить небезпечний data flow, а DAST — помилкову конфігурацію, що проявляється лише в runtime."],"exercises":["Для одного сервісу визнач findings, які очікуєш від SAST, DAST і ручної перевірки."]},"en":{"question":"Why do SAST and DAST complement each other?","answer":"SAST analyses code without running it; DAST tests a running system’s behaviour. Both have gaps and false positives.","examples":["SAST may see an unsafe data flow, while DAST finds a misconfiguration visible only at runtime."],"exercises":["For one service, identify findings expected from SAST, DAST, and manual review."]}}},{"id":"trust-boundary","direction":"security-devsecops","level":"Senior","translations":{"uk":{"question":"Що таке trust boundary?","answer":"Межа між зонами з різними рівнями довіри, через яку проходять дані або керування.","examples":["Перехід від публічного API до внутрішньої черги потребує валідації, авторизації та аудиту."],"exercises":["Побудуй STRIDE для test server і познач усі trust boundaries."]},"en":{"question":"What is a trust boundary?","answer":"A boundary between zones with different trust levels through which data or control passes.","examples":["Moving from a public API to an internal queue requires validation, authorization, and auditing."],"exercises":["Build a STRIDE model for a test server and mark every trust boundary."]}}},{"id":"queue-long-runs","direction":"system-design-cloud","level":"Middle","translations":{"uk":{"question":"Навіщо queue для довгих test runs?","answer":"Вона відділяє прийом задач від виконання й допомагає керувати навантаженням і workers; потрібні правила retries та duplicate handling.","examples":["API швидко приймає запуск, а workers забирають задачі відповідно до доступної місткості."],"exercises":["Спроєктуй Autotest Server із queue, workers і правилами повторної доставки."]},"en":{"question":"Why use a queue for long test runs?","answer":"It separates task intake from execution and helps manage load and workers; retry and duplicate-handling rules are still required.","examples":["An API accepts a run quickly while workers consume jobs according to available capacity."],"exercises":["Design an Autotest Server with a queue, workers, and redelivery rules."]}}},{"id":"rto-rpo","direction":"system-design-cloud","level":"Junior","translations":{"uk":{"question":"Чим RTO відрізняється від RPO?","answer":"RTO — цільовий час відновлення; RPO — допустиме вікно втрати даних у часі.","examples":["RTO у 30 хвилин і RPO у 5 хвилин означають різні вимоги до відновлення сервісу та резервних копій."],"exercises":["Для evidence storage запропонуй RTO/RPO й поясни вартість вибору."]},"en":{"question":"How does RTO differ from RPO?","answer":"RTO is the target recovery time; RPO is the acceptable data-loss window measured in time.","examples":["An RTO of 30 minutes and RPO of 5 minutes create different service recovery and backup requirements."],"exercises":["Propose an RTO and RPO for evidence storage and explain the cost of your choice."]}}},{"id":"retry-outage","direction":"system-design-cloud","level":"Senior","translations":{"uk":{"question":"Чому retries можуть погіршити outage?","answer":"Повторні спроби збільшують навантаження; потрібні ліміти, backoff, jitter і перевірка безпечності повторення.","examples":["Тисячі клієнтів із миттєвими retries можуть створити retry storm для вже перевантаженого сервісу."],"exercises":["Спроєктуй retry policy для нестабільного API та вкажи stop conditions."]},"en":{"question":"Why can retries make an outage worse?","answer":"Repeated attempts add load; they need limits, backoff, jitter, and a check that repetition is safe.","examples":["Thousands of clients retrying immediately can create a retry storm against an overloaded service."],"exercises":["Design a retry policy for an unstable API and define its stop conditions."]}}},{"id":"rag-purpose","direction":"ai-llm-rag-agents","level":"Junior","translations":{"uk":{"question":"Що додає RAG до LLM?","answer":"RAG витягує релевантні зовнішні матеріали й додає їх у контекст генерації; це не гарантує правильність або повноту відповіді.","examples":["Асистент може відповісти за актуальною специфікацією, але все одно неправильно її інтерпретувати."],"exercises":["Порівняй відповіді з правильним, відсутнім і суперечливим retrieval-контекстом."]},"en":{"question":"What does RAG add to an LLM?","answer":"RAG retrieves relevant external material and adds it to the generation context; it does not guarantee a correct or complete answer.","examples":["An assistant may answer from a current specification and still interpret it incorrectly."],"exercises":["Compare answers with correct, missing, and conflicting retrieval context."]}}},{"id":"agent-not-needed","direction":"ai-llm-rag-agents","level":"Middle","translations":{"uk":{"question":"Коли agent не потрібен?","answer":"Коли послідовність дій відома й може бути виконана звичайним workflow із чіткими правилами та validators.","examples":["Фіксований pipeline parse → validate → publish не потребує автономного вибору наступного кроку."],"exercises":["Перетвори один детермінований agent-сценарій на workflow і порівняй ризики."]},"en":{"question":"When is an agent unnecessary?","answer":"When the action sequence is known and a normal workflow with clear rules and validators can perform it.","examples":["A fixed parse, validate, then publish pipeline does not need autonomous next-step selection."],"exercises":["Convert one deterministic agent scenario into a workflow and compare the risks."]}}},{"id":"embeddings-permissions","direction":"ai-llm-rag-agents","level":"Senior","translations":{"uk":{"question":"Чому embeddings не замінюють permissions?","answer":"Векторна схожість визначає релевантність; право доступу потрібно перевіряти окремо до передачі контексту моделі.","examples":["Семантично близький документ іншого клієнта не стає дозволеним джерелом."],"exercises":["Спроєктуй retrieval із фільтрацією tenant і перевір спробу cross-tenant доступу."]},"en":{"question":"Why do embeddings not replace permissions?","answer":"Vector similarity measures relevance; access must be checked separately before context reaches the model.","examples":["A semantically similar document belonging to another customer does not become an authorised source."],"exercises":["Design retrieval with tenant filtering and test a cross-tenant access attempt."]}}},{"id":"evaluation-vs-demo","direction":"llmops-evaluation-observability","level":"Junior","translations":{"uk":{"question":"Чим evaluation відрізняється від одного demo?","answer":"Evaluation оцінює систему на наборі репрезентативних випадків за визначеними правилами; demo показує окремий сценарій.","examples":["Одна вдала відповідь не показує recall, стабільність або поведінку на edge cases."],"exercises":["Створи невеликий набір типових, негативних і граничних задач для одного LLM workflow."]},"en":{"question":"How does evaluation differ from a single demo?","answer":"Evaluation assesses a system on representative cases with defined rules; a demo shows one scenario.","examples":["One successful answer does not reveal recall, stability, or edge-case behaviour."],"exercises":["Create a small set of typical, negative, and boundary tasks for one LLM workflow."]}}},{"id":"llm-as-judge","direction":"llmops-evaluation-observability","level":"Middle","translations":{"uk":{"question":"Чому LLM-as-judge не є абсолютним oracle?","answer":"Judge теж може помилятися й мати bias; його треба калібрувати на людських оцінках і доповнювати deterministic checks.","examples":["Judge може стабільно віддавати перевагу довшим відповідям незалежно від їх точності."],"exercises":["Порівняй оцінки judge з людською розміткою та знайди систематичні розбіжності."]},"en":{"question":"Why is LLM-as-judge not an absolute oracle?","answer":"The judge can also be wrong and biased; it needs calibration against human ratings and deterministic checks.","examples":["A judge may consistently prefer longer answers regardless of accuracy."],"exercises":["Compare judge scores with human labels and identify systematic disagreements."]}}},{"id":"traces-and-logs","direction":"llmops-evaluation-observability","level":"Senior","translations":{"uk":{"question":"Навіщо traces поряд із logs?","answer":"Trace пов’язує кроки одного виконання й показує їх тривалість та залежності; logs фіксують окремі події.","examples":["Trace дозволяє побачити, що latency виникла в retrieval, а не під час model inference."],"exercises":["Для одного запиту визнач correlation id, spans, ключові events і поля, які не можна логувати."]},"en":{"question":"Why use traces alongside logs?","answer":"A trace connects the steps of one execution and shows timing and dependencies; logs record individual events.","examples":["A trace can reveal that latency came from retrieval rather than model inference."],"exercises":["For one request, define a correlation ID, spans, key events, and fields that must not be logged."]}}}]')},2365,(e,t,s)=>{t.exports=JSON.parse('[{"id":"boundary-value-analysis","direction":"test-design","level":"Junior","translations":{"uk":{"question":"Як працює аналіз граничних значень?","answer":"Boundary Value Analysis перевіряє значення на межі допустимого діапазону та безпосередньо поруч із нею, бо саме там часто виникають помилки порівняння й округлення. Для діапазону 1–100 базовий набір містить 0, 1, 2, 99, 100 і 101, але реальні межі можуть залежати також від типу даних і бізнес-правил.","examples":["Поле кількості квитків приймає від 1 до 10: перевіряємо 0, 1, 2, 9, 10 та 11."],"exercises":["Визначте межі для дати бронювання від сьогодні до 90 днів і складіть мінімальний набір перевірок."]},"en":{"question":"How does boundary value analysis work?","answer":"Boundary Value Analysis checks values at the edge of an allowed range and immediately around it because comparison and rounding defects often appear there. For a range of 1–100, a basic set includes 0, 1, 2, 99, 100, and 101, but real boundaries may also depend on data types and business rules.","examples":["A ticket quantity accepts 1 through 10, so we check 0, 1, 2, 9, 10, and 11."],"exercises":["Identify the boundaries for a booking date from today through 90 days and create a minimal test set."]}}},{"id":"error-guessing","direction":"test-design","level":"Junior","translations":{"uk":{"question":"Коли корисне error guessing і чого воно не замінює?","answer":"Error guessing використовує досвід із типовими дефектами: порожні значення, повторні дії, неправильний формат, timeout або зміна стану між кроками. Техніка швидка й добре доповнює формальний дизайн, але її покриття залежить від досвіду людини, тому вона не замінює систематичного аналізу вимог і ризиків.","examples":["Для форми оплати перевіряємо подвійний клік, повернення Back після підтвердження та повторне надсилання запиту."],"exercises":["Складіть десять error-guessing ідей для завантаження файлу та згрупуйте їх за джерелом ризику."]},"en":{"question":"When is error guessing useful, and what does it not replace?","answer":"Error guessing applies experience with common failures such as empty values, repeated actions, invalid formats, timeouts, or state changes between steps. It is fast and complements formal design, but its coverage depends on the tester’s experience, so it does not replace systematic requirement and risk analysis.","examples":["For a payment form, check a double click, browser Back after confirmation, and resubmitting the request."],"exercises":["Create ten error-guessing ideas for file upload and group them by risk source."]}}},{"id":"state-transition-testing","direction":"test-design","level":"Middle","translations":{"uk":{"question":"Як проєктувати перевірки для state machine?","answer":"Спочатку фіксують стани, події, дозволені переходи та guard conditions. Потім перевіряють валідні шляхи, заборонені переходи, повторення подій, відновлення після помилки й досяжність станів. Важливо тестувати не лише кінцевий статус, а й побічні ефекти переходу.","examples":["Замовлення може перейти Draft → Paid → Shipped, але перехід Draft → Shipped має бути відхилений без створення shipment."],"exercises":["Побудуйте модель станів для password reset token і створіть перевірки прострочення, повторного використання та скасування."]},"en":{"question":"How do you design tests for a state machine?","answer":"Start by identifying states, events, allowed transitions, and guard conditions. Then test valid paths, forbidden transitions, repeated events, recovery after failure, and state reachability. Verify not only the final status but also every transition’s side effects.","examples":["An order may move Draft → Paid → Shipped, while Draft → Shipped must be rejected without creating a shipment."],"exercises":["Model the states of a password-reset token and test expiry, reuse, and cancellation."]}}},{"id":"exploratory-charter","direction":"test-design","level":"Middle","translations":{"uk":{"question":"Що робить exploratory testing керованим?","answer":"Exploratory testing поєднує навчання, дизайн і виконання перевірок у межах сесії. Керованість дають charter із фокусом і ризиком, timebox, нотатки про покриття та findings, а також короткий debrief. Це не випадкове натискання кнопок, а адаптивне дослідження з видимим результатом.","examples":["Charter: дослідити відновлення checkout після втрати мережі, фокусуючись на дублюванні платежів, стані кошика та повідомленнях."],"exercises":["Напишіть 30-хвилинний charter для пошуку проблем доступності у формі реєстрації й визначте evidence сесії."]},"en":{"question":"What makes exploratory testing manageable?","answer":"Exploratory testing combines learning, test design, and execution within a session. A charter with a focus and risk, a timebox, notes about coverage and findings, and a short debrief make it manageable. It is adaptive investigation with visible outcomes, not random clicking.","examples":["Charter: explore checkout recovery after network loss, focusing on duplicate charges, cart state, and user messages."],"exercises":["Write a 30-minute charter for accessibility risks in a registration form and define the session evidence."]}}},{"id":"property-based-testing","direction":"test-design","level":"Senior","translations":{"uk":{"question":"Коли property-based testing сильніше за набір прикладів?","answer":"Property-based testing генерує багато вхідних даних і перевіряє загальні інваріанти замість кількох заздалегідь вибраних відповідей. Воно корисне для парсерів, перетворень, серіалізації та математичних правил. Якість залежить від властивостей, генераторів і shrinking; хибна властивість лише масштабуватиме хибну впевненість.","examples":["Після serialize → deserialize об’єкт має зберігати значущі поля для широкого набору згенерованих значень."],"exercises":["Сформулюйте три properties для сортування та поясніть, які дефекти не зловить перевірка лише на sorted output."]},"en":{"question":"When is property-based testing stronger than example-based tests?","answer":"Property-based testing generates many inputs and checks general invariants instead of a few predefined answers. It works well for parsers, transformations, serialization, and mathematical rules. Its value depends on sound properties, generators, and shrinking; a wrong property only scales false confidence.","examples":["After serialize → deserialize, an object should preserve its meaningful fields across a broad set of generated values."],"exercises":["Define three properties for sorting and explain which defects a check for sorted output alone would miss."]}}},{"id":"model-based-testing","direction":"test-design","level":"Senior","translations":{"uk":{"question":"Що дає model-based testing і де його межі?","answer":"Model-based testing виводить сценарії з абстрактної моделі станів, правил або потоків. Це допомагає системно покривати переходи та генерувати послідовності, які важко складати вручну. Але модель є окремим артефактом із власними помилками й вартістю підтримки, тому її доцільність залежить від стабільності домену та цінності покриття.","examples":["Модель протоколу підписки генерує шляхи активації, паузи, відновлення, скасування та заборонені переходи."],"exercises":["Порівняйте ручний набір сценаріїв і модель станів для workflow погодження документа; визначте maintenance cost."]},"en":{"question":"What does model-based testing provide, and where are its limits?","answer":"Model-based testing derives scenarios from an abstract model of states, rules, or flows. It systematically covers transitions and can generate sequences that are hard to design manually. The model is another artefact with its own defects and maintenance cost, so its value depends on domain stability and the importance of coverage.","examples":["A subscription protocol model generates activation, pause, resume, cancellation, and forbidden transition paths."],"exercises":["Compare a manual scenario set with a state model for document approval and estimate the maintenance cost."]}}},{"id":"test-pyramid-feedback","direction":"automation-architecture","level":"Junior","translations":{"uk":{"question":"Навіщо автоматизації test pyramid, якщо це не сувора формула?","answer":"Test pyramid нагадує розміщувати більшість перевірок на швидких і локальних рівнях, а дорогі end-to-end сценарії залишати для ризиків, які не можна покрити нижче. Форма залежить від архітектури продукту; мета — короткий feedback, діагностичність і прийнятна вартість підтримки, а не правильна кількість тестів у кожному шарі.","examples":["Правило розрахунку перевіряється unit-тестами, контракт інтеграції — API-тестами, а один критичний шлях — через UI."],"exercises":["Розкладіть десять перевірок знайомої функції за рівнями й обґрунтуйте найдорожчі end-to-end сценарії."]},"en":{"question":"Why use the test pyramid if it is not a strict formula?","answer":"The test pyramid encourages most checks to live at fast, local levels while expensive end-to-end scenarios cover risks that cannot be addressed below. Its shape depends on the product architecture; the goal is fast feedback, useful diagnostics, and sustainable maintenance rather than a prescribed test count per layer.","examples":["A calculation rule is covered by unit tests, an integration contract by API tests, and one critical journey through the UI."],"exercises":["Place ten checks for a familiar feature across test levels and justify the most expensive end-to-end cases."]}}},{"id":"deterministic-waits","direction":"automation-architecture","level":"Junior","translations":{"uk":{"question":"Чому fixed sleep робить автоматизацію нестабільною?","answer":"Фіксована пауза не знає, коли система справді готова: короткий sleep дає flaky failures, довгий сповільнює suite. Краще чекати на спостережувану умову з обмеженим timeout — відповідь API, стан елемента, завершення job або появу події — і зберігати діагностику при перевищенні часу.","examples":["Замість sleep(5000) тест очікує, доки статус операції стане Completed, але не довше 10 секунд."],"exercises":["Знайдіть три fixed sleeps у тестовому сценарії та замініть кожен на конкретну умову готовності."]},"en":{"question":"Why does a fixed sleep make automation unstable?","answer":"A fixed delay does not know when the system is actually ready: a short sleep causes flaky failures, while a long one slows the suite. Wait for an observable condition with a bounded timeout—an API response, element state, completed job, or emitted event—and preserve diagnostics when the timeout expires.","examples":["Instead of sleep(5000), the test waits until the operation status becomes Completed, for at most ten seconds."],"exercises":["Find three fixed sleeps in a test scenario and replace each with a specific readiness condition."]}}},{"id":"fixtures-and-test-data","direction":"automation-architecture","level":"Middle","translations":{"uk":{"question":"Як fixtures допомагають ізолювати автоматизовані тести?","answer":"Fixture готує контрольований стан, надає ресурс тесту й виконує cleanup. Хороша fixture має явний scope, створює мінімальні дані, не приховує важливі передумови та безпечно працює паралельно. Спільний mutable state між тестами породжує залежність від порядку й складні для відтворення падіння.","examples":["Кожен тест створює користувача з унікальним namespace через API та видаляє його після завершення, навіть якщо assertion впав."],"exercises":["Спроєктуйте fixture для паралельних tests замовлення: setup, унікальність, cleanup і поведінка при частковому падінні."]},"en":{"question":"How do fixtures help isolate automated tests?","answer":"A fixture prepares controlled state, provides a resource to the test, and performs cleanup. A good fixture has explicit scope, creates minimal data, does not hide important preconditions, and is safe under parallel execution. Shared mutable state creates order dependence and failures that are difficult to reproduce.","examples":["Each test creates a user in a unique namespace through the API and deletes it afterwards, even when an assertion fails."],"exercises":["Design a fixture for parallel order tests, including setup, uniqueness, cleanup, and partial-failure behaviour."]}}},{"id":"service-virtualization","direction":"automation-architecture","level":"Middle","translations":{"uk":{"question":"Коли service virtualization корисніша за реальну залежність?","answer":"Віртуальний сервіс дає контрольовані відповіді, помилки, latency та рідкісні послідовності без залежності від доступності зовнішньої системи. Він пришвидшує feedback і робить негативні сценарії відтворюваними. Але virtual service не доводить реальну сумісність, тому його потрібно доповнювати contract tests і вибраними інтеграційними перевірками.","examples":["Stub платіжного провайдера послідовно повертає timeout, duplicate callback і success, щоб перевірити retry logic."],"exercises":["Оберіть одну нестабільну інтеграцію й опишіть, що симулювати, а що обов’язково залишити для real-environment test."]},"en":{"question":"When is service virtualization more useful than a real dependency?","answer":"A virtual service provides controlled responses, failures, latency, and rare sequences without depending on an external system’s availability. It speeds feedback and makes negative scenarios reproducible. It does not prove real compatibility, so combine it with contract tests and selected integration checks.","examples":["A payment-provider stub returns a timeout, duplicate callback, and success in sequence to test retry logic."],"exercises":["Choose one unstable integration and define what to simulate and what must remain a real-environment test."]}}},{"id":"contract-testing-boundaries","direction":"automation-architecture","level":"Senior","translations":{"uk":{"question":"Яку проблему розв’язує contract testing між сервісами?","answer":"Contract testing перевіряє, що provider і consumer узгоджено розуміють запити, відповіді та сумісні зміни на межі сервісів. Consumer-driven підхід фіксує реально потрібну поведінку, а schema validation — форму повідомлення. Контракти не перевіряють повний бізнес-процес, production configuration чи семантику всіх даних.","examples":["Consumer очікує поле currency та конкретну поведінку для 404; provider verification запускає ці очікування перед релізом."],"exercises":["Для двох сервісів визначте contract, ownership, правила versioning і сценарій, який усе одно потребує end-to-end test."]},"en":{"question":"What problem does contract testing solve between services?","answer":"Contract testing checks that providers and consumers agree on requests, responses, and compatible changes at service boundaries. A consumer-driven approach captures behaviour that clients actually need, while schema validation checks message shape. Contracts do not verify complete business flows, production configuration, or every data semantic.","examples":["A consumer expects a currency field and specific 404 behaviour; provider verification runs those expectations before release."],"exercises":["For two services, define the contract, ownership, versioning rules, and one scenario that still needs an end-to-end test."]}}},{"id":"parallel-execution-observability","direction":"automation-architecture","level":"Senior","translations":{"uk":{"question":"Що потрібно архітектурі тестів для безпечного parallel execution?","answer":"Паралельність потребує ізольованих даних і ресурсів, контрольованої конкуренції, незалежних тестів та кореляційних ідентифікаторів. Логи, traces, screenshots і мережеві артефакти мають прив’язуватися до конкретного worker і test run. Інакше прискорення лише створює race conditions, шум і нерозбірливі падіння.","examples":["Кожен worker отримує окремий tenant і correlation ID, а звіт збирає всі запити та події одного тесту."],"exercises":["Підготуйте план переходу suite з 1 на 8 workers: ресурси, ліміти, isolation та evidence при failure."]},"en":{"question":"What does a test architecture need for safe parallel execution?","answer":"Parallelism requires isolated data and resources, controlled concurrency, independent tests, and correlation identifiers. Logs, traces, screenshots, and network artefacts must map to a specific worker and test run. Otherwise, speed merely creates race conditions, noise, and failures that cannot be diagnosed.","examples":["Each worker receives a separate tenant and correlation ID, while the report gathers every request and event for one test."],"exercises":["Plan a suite migration from one to eight workers, covering resources, limits, isolation, and failure evidence."]}}},{"id":"python-identity-equality","direction":"python-coding-whiteboard","level":"Junior","translations":{"uk":{"question":"Чим у Python відрізняються is та ==?","answer":"Оператор == порівнює значення через equality protocol, а is перевіряє, чи дві змінні посилаються на той самий об’єкт. is доречний для singleton-значень на кшталт None; використовувати його для рядків або чисел небезпечно через деталі інтернування.","examples":["value is None — коректна перевірка; value == expected — порівняння змісту."],"exercises":["Напишіть приклади, де два окремі списки рівні за ==, але is повертає False, і поясніть результат."]},"en":{"question":"How do is and == differ in Python?","answer":"The == operator compares values through the equality protocol, while is checks whether two names refer to the same object. is is appropriate for singleton values such as None; using it for strings or numbers is unsafe because of interning details.","examples":["value is None is a correct identity check; value == expected compares content."],"exercises":["Write an example where two separate lists are equal with == but is returns False, and explain why."]}}},{"id":"python-context-manager","direction":"python-coding-whiteboard","level":"Junior","translations":{"uk":{"question":"Навіщо Python context manager?","answer":"Context manager описує вхід у контрольований контекст і гарантований вихід із нього, навіть коли всередині виникає exception. Він підходить для файлів, locks, транзакцій, тимчасових ресурсів і тестових fixtures, бо тримає setup та cleanup поруч.","examples":["with open(...) закриває файл автоматично; власний context manager може відкотити тестову транзакцію."],"exercises":["Створіть context manager для тимчасового environment variable, який завжди відновлює попереднє значення."]},"en":{"question":"Why use a Python context manager?","answer":"A context manager defines entry into a controlled context and guaranteed exit, even when an exception occurs inside it. It suits files, locks, transactions, temporary resources, and test fixtures because setup and cleanup stay together.","examples":["with open(...) closes a file automatically; a custom context manager can roll back a test transaction."],"exercises":["Create a context manager for a temporary environment variable that always restores the previous value."]}}},{"id":"python-type-hints-contracts","direction":"python-coding-whiteboard","level":"Middle","translations":{"uk":{"question":"Що дають type hints у динамічному Python?","answer":"Type hints документують очікувані контракти й дозволяють static checker знайти частину помилок до runtime. Вони не виконують автоматичну runtime validation і не замінюють тести. Найбільша користь з’являється на межах модулів, у складних структурах даних і під час refactoring.","examples":["Protocol описує потрібну поведінку API client без жорсткої залежності від конкретного класу."],"exercises":["Додайте typing до функції нормалізації API response й перевірте обробку Optional та union values."]},"en":{"question":"What do type hints provide in dynamic Python?","answer":"Type hints document expected contracts and let a static checker catch some errors before runtime. They do not automatically validate values at runtime and do not replace tests. Their greatest value appears at module boundaries, in complex data structures, and during refactoring.","examples":["A Protocol describes the behaviour required from an API client without coupling code to one concrete class."],"exercises":["Add typing to an API-response normalizer and handle Optional and union values explicitly."]}}},{"id":"python-exception-paths","direction":"python-coding-whiteboard","level":"Middle","translations":{"uk":{"question":"Як тестувати exception paths без маскування помилок?","answer":"Тест має викликати конкретну умову, перевірити тип і значущі атрибути exception, а також стан після помилки. Broad except або порожній catch приховує дефекти. Для retryable помилок окремо перевіряють кількість спроб, backoff і те, що non-retryable exception не повторюється.","examples":["pytest.raises перевіряє ValidationError і поле invalid_field, а fixture підтверджує, що запис у базі не створено."],"exercises":["Протестуйте функцію з timeout, validation error і unexpected error; визначте різну політику для кожної."]},"en":{"question":"How do you test exception paths without hiding errors?","answer":"A test should trigger a specific condition, assert the exception type and meaningful attributes, and verify state after failure. A broad except or empty catch hides defects. For retryable failures, separately verify attempt count, backoff, and that non-retryable exceptions are not repeated.","examples":["pytest.raises checks ValidationError and its invalid_field attribute, while a fixture confirms that no database row was created."],"exercises":["Test a function for timeout, validation error, and unexpected error, defining a different policy for each."]}}},{"id":"python-async-cancellation","direction":"python-coding-whiteboard","level":"Senior","translations":{"uk":{"question":"Чому cancellation і timeout є частиною дизайну async-коду?","answer":"Async task може бути скасована під час будь-якого await, тому код має коректно звільняти ресурси й не залишати частково змінений стан. Timeout задає межу очікування, але не завжди зупиняє зовнішню операцію. Structured concurrency допомагає пов’язати життєвий цикл дочірніх tasks із батьківською операцією.","examples":["Після timeout HTTP-запиту context manager закриває session, а незавершені дочірні tasks скасовуються та awaited."],"exercises":["Спроєктуйте async fan-out до трьох сервісів із загальним deadline, частковими результатами та cleanup."]},"en":{"question":"Why are cancellation and timeout part of async-code design?","answer":"An async task can be cancelled at any await, so code must release resources correctly and avoid leaving partially changed state. A timeout bounds waiting but does not always stop the external operation. Structured concurrency helps tie child-task lifecycles to their parent operation.","examples":["After an HTTP timeout, a context manager closes the session, and unfinished child tasks are cancelled and awaited."],"exercises":["Design an async fan-out to three services with a shared deadline, partial results, and cleanup."]}}},{"id":"python-complexity-review","direction":"python-coding-whiteboard","level":"Senior","translations":{"uk":{"question":"Як оцінювати complexity під час coding whiteboard і code review?","answer":"Big-O описує, як ростуть витрати зі збільшенням input, але практичний review враховує також розмір даних, memory, I/O, читабельність і профілювання. Правильна відповідь пояснює assumptions та trade-offs, а не просто називає O(n). Оптимізація без вимірювання може ускладнити код без користі.","examples":["Заміна вкладеного пошуку списком на set зменшує очікуваний час із O(n²) до O(n), використовуючи додаткову пам’ять."],"exercises":["Порівняйте два способи пошуку дублікатів і поясніть вибір для 100 та 10 мільйонів елементів."]},"en":{"question":"How should complexity be assessed in a coding whiteboard or code review?","answer":"Big-O describes how cost grows with input, but practical review also considers data size, memory, I/O, readability, and profiling. A strong answer states assumptions and trade-offs instead of merely naming O(n). Optimising without measurement may complicate code without benefit.","examples":["Replacing nested list lookup with a set reduces expected time from O(n²) to O(n) while using additional memory."],"exercises":["Compare two duplicate-detection approaches and justify the choice for 100 and 10 million elements."]}}},{"id":"typescript-structural-typing","direction":"typescript-playwright-bdd","level":"Junior","translations":{"uk":{"question":"Що означає structural typing у TypeScript?","answer":"TypeScript перевіряє сумісність переважно за формою значення: об’єкт підходить, якщо має потрібні поля й типи, незалежно від назви класу. Це зручно для API та dependency injection, але compile-time типи зникають у runtime, тому зовнішні дані все одно потребують validation.","examples":["Функція приймає об’єкт із методом send(); будь-яка реалізація з сумісною сигнатурою відповідає контракту."],"exercises":["Опишіть interface для API client і покажіть, чому JSON response не стає безпечним лише після type assertion."]},"en":{"question":"What does structural typing mean in TypeScript?","answer":"TypeScript checks compatibility mainly by value shape: an object fits when it has the required fields and types, regardless of its class name. This is convenient for APIs and dependency injection, but compile-time types disappear at runtime, so external data still needs validation.","examples":["A function accepts an object with a send() method; any implementation with a compatible signature satisfies the contract."],"exercises":["Define an interface for an API client and show why a type assertion alone does not make a JSON response safe."]}}},{"id":"playwright-stable-locators","direction":"typescript-playwright-bdd","level":"Junior","translations":{"uk":{"question":"Як вибирати стабільні locators у Playwright?","answer":"Перевагу варто надавати user-facing семантиці: role, accessible name, label або стабільному test id. Довгі CSS/XPath-селектори прив’язуються до випадкової структури DOM і часто ламаються після верстки. Locator має однозначно описувати намір і падати, якщо елементів несподівано кілька.","examples":["getByRole(\'button\', { name: \'Save\' }) краще передає поведінку, ніж div:nth-child(3) > button."],"exercises":["Перепишіть п’ять крихких CSS selectors через role, label або test id і поясніть кожен вибір."]},"en":{"question":"How should stable Playwright locators be chosen?","answer":"Prefer user-facing semantics such as role, accessible name, label, or a stable test id. Long CSS or XPath selectors couple tests to incidental DOM structure and often break after layout changes. A locator should express intent clearly and fail when it unexpectedly matches multiple elements.","examples":["getByRole(\'button\', { name: \'Save\' }) expresses behaviour better than div:nth-child(3) > button."],"exercises":["Rewrite five brittle CSS selectors using role, label, or test id and explain each choice."]}}},{"id":"playwright-web-first-assertions","direction":"typescript-playwright-bdd","level":"Middle","translations":{"uk":{"question":"Чим web-first assertions відрізняються від миттєвої перевірки?","answer":"Web-first assertion повторно читає стан через locator до успіху або timeout, враховуючи асинхронні оновлення UI. Миттєва перевірка snapshot-значення легко потрапляє між render cycles. Очікування має бути спрямоване на бізнесово значущий стан, а не приховувати нескінченне завантаження великим timeout.","examples":["expect(locator).toHaveText(\'Paid\') чекає потрібний стан, тоді як перевірка textContent одразу може побачити старе значення."],"exercises":["Замініть polling вручну та fixed sleep на web-first assertions у сценарії з асинхронним status update."]},"en":{"question":"How do web-first assertions differ from immediate checks?","answer":"A web-first assertion repeatedly reads state through a locator until success or timeout, accounting for asynchronous UI updates. An immediate snapshot check can land between render cycles. Wait for a business-meaningful state rather than hiding endless loading behind a large timeout.","examples":["expect(locator).toHaveText(\'Paid\') waits for the target state, while immediately checking textContent may see the old value."],"exercises":["Replace manual polling and fixed sleep with web-first assertions in a scenario with an asynchronous status update."]}}},{"id":"playwright-fixtures","direction":"typescript-playwright-bdd","level":"Middle","translations":{"uk":{"question":"Як використовувати Playwright fixtures без прихованої магії?","answer":"Fixtures мають надавати чітко названі ресурси з відповідним scope і автоматичним cleanup. Worker-scoped fixture підходить для дорогого read-only setup, test-scoped — для змінного стану. Надмірно велика auto fixture приховує залежності та робить тест складним для читання й діагностики.","examples":["authPage створює ізольований context для кожного тесту, а API client із базовою конфігурацією може бути worker-scoped."],"exercises":["Розділіть одну велику fixture на auth, data setup і page objects; оберіть scope та cleanup для кожної."]},"en":{"question":"How can Playwright fixtures be used without hidden magic?","answer":"Fixtures should provide clearly named resources with an appropriate scope and automatic cleanup. A worker-scoped fixture suits expensive read-only setup, while test scope suits mutable state. An oversized automatic fixture hides dependencies and makes tests difficult to read and diagnose.","examples":["authPage creates an isolated context per test, while an API client with base configuration can be worker-scoped."],"exercises":["Split one large fixture into authentication, data setup, and page objects; choose scope and cleanup for each."]}}},{"id":"playwright-network-mocking","direction":"typescript-playwright-bdd","level":"Senior","translations":{"uk":{"question":"Коли network mocking у browser test виправданий?","answer":"Mocking корисний для детермінованих помилок, повільних залежностей і UI-станів, які важко відтворити. Він дозволяє перевірити frontend окремо, але створює ризик розходження з реальним API. Контракт fixture має бути перевірений, а критичні flows — додатково пройти з реальною інтеграцією.","examples":["route.fulfill повертає 429 із Retry-After для перевірки повідомлення й повторної дії користувача."],"exercises":["Визначте три сценарії для mock і два для real backend; опишіть захист від застарілого response fixture."]},"en":{"question":"When is network mocking in a browser test justified?","answer":"Mocking is useful for deterministic failures, slow dependencies, and UI states that are hard to reproduce. It isolates frontend behaviour but risks drifting from the real API. Validate fixture contracts and additionally run critical flows against the real integration.","examples":["route.fulfill returns 429 with Retry-After to test the message and the user’s retry action."],"exercises":["Choose three scenarios for mocks and two for a real backend, then define protection against stale response fixtures."]}}},{"id":"playwright-trace-parallelism","direction":"typescript-playwright-bdd","level":"Senior","translations":{"uk":{"question":"Як traces допомагають діагностувати паралельні Playwright tests?","answer":"Trace об’єднує actions, DOM snapshots, network, console та timing для конкретного тесту. У CI це значно корисніше за один screenshot, особливо при race condition. Trace потрібно зберігати за зрозумілою retention policy, не записувати secrets і поєднувати з унікальними test data для відтворення.","examples":["Trace показує, що worker B змінив спільне замовлення між click і assertion worker A."],"exercises":["Налаштуйте trace on-first-retry та перелічіть дані, які потрібні, щоб відрізнити product defect від test isolation issue."]},"en":{"question":"How do traces help diagnose parallel Playwright tests?","answer":"A trace combines actions, DOM snapshots, network, console, and timing for one test. In CI this is much more useful than a single screenshot, especially for race conditions. Store traces under a clear retention policy, avoid secrets, and pair them with unique test data for reproduction.","examples":["A trace shows that worker B changed a shared order between worker A’s click and assertion."],"exercises":["Configure trace on-first-retry and list the evidence needed to separate a product defect from a test-isolation issue."]}}}]')},8403,(e,t,s)=>{t.exports=JSON.parse('[{"id":"http-message-anatomy","direction":"web-http-networking","level":"Junior","translations":{"uk":{"question":"З чого складаються HTTP request і response?","answer":"Request містить method, target, headers і, за потреби, body. Response повертає status code, headers і body. Семантика важливіша за синтаксис: однаковий JSON може означати різне залежно від method, content type, cache directives та стану ресурсу.","examples":["POST /orders із JSON body створює ресурс, а response 201 містить Location нового замовлення."],"exercises":["Розберіть один request/response у DevTools: method, URL, headers, body, status і cache policy."]},"en":{"question":"What are HTTP requests and responses made of?","answer":"A request contains a method, target, headers, and optionally a body. A response returns a status code, headers, and a body. Semantics matter more than syntax: identical JSON can mean different things depending on the method, content type, cache directives, and resource state.","examples":["POST /orders with a JSON body creates a resource, while a 201 response includes the new order’s Location."],"exercises":["Inspect one request and response in DevTools: method, URL, headers, body, status, and cache policy."]}}},{"id":"dns-tcp-tls-path","direction":"web-http-networking","level":"Junior","translations":{"uk":{"question":"Що відбувається в мережі до першої HTTPS-відповіді?","answer":"Клієнт зазвичай знаходить IP через DNS, встановлює транспортне з’єднання, узгоджує TLS і лише потім обмінюється HTTP. DNS, routing, certificate validation або handshake можуть зламатися до того, як application server побачить запит. HTTP/3 змінює транспорт, але не скасовує потребу розуміти ці шари.","examples":["Expired certificate дає помилку браузера, хоча endpoint і бізнес-логіка сервера справні."],"exercises":["Для помилки «site unavailable» складіть діагностичне дерево від DNS до application response."]},"en":{"question":"What happens on the network before the first HTTPS response?","answer":"A client typically resolves an IP through DNS, establishes transport, negotiates TLS, and only then exchanges HTTP. DNS, routing, certificate validation, or the handshake can fail before the application server sees a request. HTTP/3 changes the transport but not the need to understand these layers.","examples":["An expired certificate causes a browser error even when the endpoint and server business logic are healthy."],"exercises":["Create a diagnostic tree for “site unavailable,” from DNS through the application response."]}}},{"id":"http-caching-validation","direction":"web-http-networking","level":"Middle","translations":{"uk":{"question":"Як HTTP caching впливає на поведінку, яку бачить користувач?","answer":"Cache-Control визначає, де й як довго можна повторно використовувати response; ETag і Last-Modified дозволяють revalidation. Дефекти виникають через застарілі дані, неправильний cache key, кешування приватного response або відсутню invalidation. Перевіряти потрібно browser, CDN і origin як окремі шари.","examples":["Response профілю без Vary: Authorization може випадково потрапити не тому користувачу через shared cache."],"exercises":["Спроєктуйте перевірки cache hit, revalidation, invalidation і private data для одного GET endpoint."]},"en":{"question":"How does HTTP caching affect behaviour visible to users?","answer":"Cache-Control defines where and how long a response may be reused; ETag and Last-Modified support revalidation. Defects arise from stale data, incorrect cache keys, cached private responses, or missing invalidation. Test the browser, CDN, and origin as separate layers.","examples":["A profile response without Vary: Authorization could reach the wrong user through a shared cache."],"exercises":["Design cache-hit, revalidation, invalidation, and private-data checks for one GET endpoint."]}}},{"id":"cookies-sessions-csrf","direction":"web-http-networking","level":"Middle","translations":{"uk":{"question":"Як cookies пов’язані із sessions і CSRF?","answer":"Browser автоматично додає відповідні cookies до запиту, тому session cookie зберігає ідентичність між stateless HTTP exchanges. Атрибути Secure, HttpOnly і SameSite зменшують окремі ризики, але не замінюють CSRF protection та server-side session controls. Domain, path і expiry теж впливають на область дії.","examples":["SameSite=Lax обмежує частину cross-site запитів, але sensitive endpoint усе одно потребує правильної моделі CSRF-захисту."],"exercises":["Перевірте login session: rotation, logout invalidation, expiry, parallel devices і cookie attributes."]},"en":{"question":"How are cookies related to sessions and CSRF?","answer":"A browser automatically attaches matching cookies to requests, allowing a session cookie to carry identity across stateless HTTP exchanges. Secure, HttpOnly, and SameSite reduce particular risks but do not replace CSRF protection or server-side session controls. Domain, path, and expiry also define scope.","examples":["SameSite=Lax limits some cross-site requests, but a sensitive endpoint still needs an appropriate CSRF defence model."],"exercises":["Test a login session for rotation, logout invalidation, expiry, parallel devices, and cookie attributes."]}}},{"id":"reverse-proxy-load-balancer","direction":"web-http-networking","level":"Senior","translations":{"uk":{"question":"Як reverse proxy і load balancer змінюють тестову поверхню?","answer":"Проміжні компоненти можуть завершувати TLS, переписувати headers, маршрутизувати за host/path, робити retries, rate limiting і health checks. Через це поведінка прямого backend call не гарантує поведінку production path. Потрібно перевіряти forwarded identity, timeout budgets, sticky sessions і реакцію на partial failure.","examples":["Proxy retry небезпечного POST після timeout може створити дубль, якщо endpoint не має idempotency protection."],"exercises":["Намалюйте production request path і визначте по одному failure mode для DNS, CDN, proxy, balancer та service."]},"en":{"question":"How do reverse proxies and load balancers change the test surface?","answer":"Intermediaries may terminate TLS, rewrite headers, route by host or path, retry, rate-limit, and perform health checks. A direct backend call therefore does not prove production-path behaviour. Test forwarded identity, timeout budgets, sticky sessions, and partial-failure handling.","examples":["A proxy retry of an unsafe POST after timeout may create a duplicate unless the endpoint has idempotency protection."],"exercises":["Draw the production request path and identify one failure mode for DNS, CDN, proxy, balancer, and service."]}}},{"id":"browser-security-boundaries","direction":"web-http-networking","level":"Senior","translations":{"uk":{"question":"Які browser security boundaries важливі для тестування web application?","answer":"Це різні механізми, і жоден не виправляє слабку server-side authorization:","answerPoints":["Same-origin policy обмежує читання ресурсів між origins.","CORS надає контрольовані винятки.","CSP обмежує джерела executable content.","Sandbox та permission policies звужують можливості embedded content."],"examples":["CORS дозволяє frontend прочитати response, але backend усе одно має перевірити право користувача на конкретний order."],"exercises":["Для application з iframe й API складіть матрицю origin, credentials, CORS, CSP та authorization expectations."]},"en":{"question":"Which browser security boundaries matter when testing a web application?","answer":"These mechanisms solve different problems, and none repairs weak server-side authorization:","answerPoints":["The same-origin policy limits reading resources across origins.","CORS provides controlled exceptions.","CSP restricts executable-content sources.","Sandbox and permission policies narrow embedded-content capabilities."],"examples":["CORS lets a frontend read a response, but the backend must still verify the user’s access to that specific order."],"exercises":["For an application with an iframe and API, build a matrix of origin, credentials, CORS, CSP, and authorization expectations."]}}},{"id":"rest-resource-semantics","direction":"api-sql-data","level":"Junior","translations":{"uk":{"question":"Що означає resource-oriented REST API на практиці?","answer":"Resource має стабільну identity, representation і операції з узгодженою HTTP-семантикою. URI зазвичай називає ресурс, method виражає дію, status і headers пояснюють результат. REST не зводиться до JSON over HTTP: важливі statelessness, cacheability та однакові правила помилок.","examples":["PATCH /users/42 змінює частину representation, а GET того самого URI повертає актуальний стан."],"exercises":["Переробіть RPC-подібні endpoints createOrder/cancelOrder у resource model і поясніть trade-offs."]},"en":{"question":"What does a resource-oriented REST API mean in practice?","answer":"A resource has a stable identity, representations, and operations with consistent HTTP semantics. A URI usually names the resource, the method expresses the action, and status plus headers explain the result. REST is more than JSON over HTTP: statelessness, cacheability, and consistent error rules also matter.","examples":["PATCH /users/42 changes part of a representation, while GET on the same URI returns the current state."],"exercises":["Redesign RPC-like createOrder and cancelOrder endpoints as resources and explain the trade-offs."]}}},{"id":"sql-joins-cardinality","direction":"api-sql-data","level":"Junior","translations":{"uk":{"question":"Як JOIN і cardinality впливають на правильність SQL result?","answer":"INNER JOIN залишає рядки з відповідністю, LEFT JOIN зберігає всі рядки зліва, а many-to-many зв’язок може помножити результат. Перед aggregate потрібно розуміти grain кожної таблиці та очікувану cardinality, інакше COUNT або SUM виглядатиме правдоподібно, але буде завищеним.","examples":["JOIN orders з order_items повертає один order кілька разів; SUM(order.total) після такого JOIN подвоює дані."],"exercises":["Створіть набір із відсутнім match, одним match і кількома matches та порівняйте INNER і LEFT JOIN."]},"en":{"question":"How do JOINs and cardinality affect SQL result correctness?","answer":"An INNER JOIN keeps matching rows, a LEFT JOIN preserves all rows on the left, and a many-to-many relationship can multiply results. Understand each table’s grain and expected cardinality before aggregating, or COUNT and SUM may look plausible while being inflated.","examples":["Joining orders to order_items returns one order multiple times; SUM(order.total) after that join duplicates the total."],"exercises":["Create data with no match, one match, and multiple matches, then compare INNER and LEFT JOIN results."]}}},{"id":"api-pagination-ordering","direction":"api-sql-data","level":"Middle","translations":{"uk":{"question":"Чому pagination потребує стабільного ordering?","answer":"Без детермінованого порядку записи можуть дублюватися або зникати між pages. Offset pagination проста, але чутлива до вставок і повільна на великих offsets; cursor pagination краще працює з послідовними ключами, але має складніший контракт. Фільтри та sort fields також потрібно валідувати.","examples":["Сортування лише за created_at неоднозначне; додатковий id створює стабільний tie-breaker."],"exercises":["Спроєктуйте перевірки pagination при одночасній вставці й видаленні записів та порівняйте offset із cursor."]},"en":{"question":"Why does pagination require stable ordering?","answer":"Without deterministic order, records may be duplicated or disappear between pages. Offset pagination is simple but sensitive to inserts and slow at large offsets; cursor pagination works better with sequential keys but has a more complex contract. Filters and sort fields also require validation.","examples":["Sorting only by created_at is ambiguous; adding id provides a stable tie-breaker."],"exercises":["Design pagination tests during concurrent inserts and deletes, comparing offset and cursor behaviour."]}}},{"id":"transaction-isolation-anomalies","direction":"api-sql-data","level":"Middle","translations":{"uk":{"question":"Які аномалії може дозволити transaction isolation level?","answer":"Слабші рівні можуть дозволяти non-repeatable reads, phantoms або lost updates залежно від СУБД та конкретної реалізації. Назва isolation level сама по собі не є достатнім oracle. Конкурентний тест має керувати порядком транзакцій і перевіряти фінальний інваріант, а не покладатися на випадковий timing.","examples":["Два клієнти одночасно списують останню одиницю товару; без правильної синхронізації stock стає від’ємним."],"exercises":["Створіть детермінований тест lost update із двома connections і визначте очікування для обраної СУБД."]},"en":{"question":"Which anomalies can a transaction isolation level permit?","answer":"Weaker levels may allow non-repeatable reads, phantoms, or lost updates depending on the database and its implementation. The isolation-level name alone is not a sufficient oracle. A concurrency test should control transaction order and verify the final invariant instead of relying on accidental timing.","examples":["Two clients simultaneously buy the final stock item; without correct synchronization, inventory becomes negative."],"exercises":["Build a deterministic lost-update test with two connections and define expectations for your chosen database."]}}},{"id":"database-migration-safety","direction":"api-sql-data","level":"Senior","translations":{"uk":{"question":"Як перевіряти database migration без ризику для rollout?","answer":"Перевіряють schema change, data backfill, compatibility старої й нової версій application, locking, тривалість та rollback/roll-forward strategy. Для zero-downtime зміни часто потрібні expand–migrate–contract етапи. Production-like обсяг даних важливий, бо швидка migration на порожній базі нічого не доводить.","examples":["Нову nullable column спочатку додають, потім backfill, переводять readers і лише згодом вводять constraint."],"exercises":["Складіть план безпечного перейменування column із mixed-version deployment та контрольними метриками."]},"en":{"question":"How can a database migration be tested without risking rollout?","answer":"Test the schema change, data backfill, compatibility with old and new application versions, locking, duration, and rollback or roll-forward strategy. Zero-downtime changes often require expand–migrate–contract stages. Production-like data volume matters because a fast migration on an empty database proves little.","examples":["Add a nullable column first, backfill it, move readers, and only later introduce the constraint."],"exercises":["Plan a safe column rename with mixed-version deployment and monitoring signals."]}}},{"id":"api-idempotency-consistency","direction":"api-sql-data","level":"Senior","translations":{"uk":{"question":"Як тестувати idempotency при retries і eventual consistency?","answer":"Повтор одного logical request з тим самим key має давати узгоджений результат без повторного side effect. Потрібно перевіряти concurrent duplicates, timeout після commit, expiry ключа та різний payload із тим самим key. За eventual consistency assertions мають враховувати bounded convergence, але не маскувати нескінченну затримку.","examples":["Клієнт не отримав response після створення платежу й повторив POST; система повертає той самий payment, а не створює другий."],"exercises":["Спроєктуйте матрицю idempotency для success, timeout, parallel retry, changed payload і expired key."]},"en":{"question":"How do you test idempotency with retries and eventual consistency?","answer":"Repeating one logical request with the same key should produce a consistent result without repeating the side effect. Test concurrent duplicates, timeout after commit, key expiry, and a different payload with the same key. Under eventual consistency, assertions should allow bounded convergence without hiding an endless delay.","examples":["A client misses the payment-creation response and repeats POST; the system returns the same payment instead of creating another."],"exercises":["Design an idempotency matrix for success, timeout, parallel retry, changed payload, and expired key."]}}},{"id":"pipeline-stages-feedback","direction":"cicd-docker-kubernetes","level":"Junior","translations":{"uk":{"question":"Як організувати stages CI pipeline для швидкого feedback?","answer":"Дешеві й швидкі перевірки запускають раніше: formatting, static analysis, unit tests, потім build, integration, security та дорожчі system tests. Незалежні jobs виконують паралельно, а fail-fast не повинен знищувати потрібну діагностику. Кожен stage має зрозумілий purpose та artifact.","examples":["Lint і unit tests завершуються за хвилини до запуску container integration suite на десятки хвилин."],"exercises":["Перебудуйте pipeline з десяти перевірок за вартістю, сигналом і залежностями; визначте parallel jobs."]},"en":{"question":"How should CI pipeline stages be organised for fast feedback?","answer":"Run cheap, fast checks first: formatting, static analysis, and unit tests, followed by build, integration, security, and expensive system tests. Execute independent jobs in parallel, and ensure fail-fast does not destroy useful diagnostics. Every stage should have a clear purpose and artefact.","examples":["Lint and unit tests finish within minutes before a container integration suite that takes much longer."],"exercises":["Reorder ten pipeline checks by cost, signal, and dependencies, then identify parallel jobs."]}}},{"id":"build-artifacts-versioning","direction":"cicd-docker-kubernetes","level":"Junior","translations":{"uk":{"question":"Чому build artifact потрібно створювати один раз?","answer":"Один immutable artifact має проходити перевірки й просуватися між environments. Повторний build для production може використати інші dependencies або configuration і зруйнувати доказ, отриманий у CI. Artifact ідентифікують version, commit digest та provenance, а configuration додають окремо під час deployment.","examples":["Той самий container digest тестують у staging і deploy у production, замість повторного docker build."],"exercises":["Опишіть metadata для traceability artifact: source commit, dependencies, build run, signature і environment config."]},"en":{"question":"Why should a build artefact be created only once?","answer":"One immutable artefact should pass checks and be promoted across environments. Rebuilding for production may use different dependencies or configuration and invalidate CI evidence. Identify artefacts by version, commit digest, and provenance, while applying environment configuration separately during deployment.","examples":["Test the same container digest in staging and deploy it to production instead of running docker build again."],"exercises":["Define traceability metadata for an artefact: source commit, dependencies, build run, signature, and environment configuration."]}}},{"id":"pipeline-secrets-permissions","direction":"cicd-docker-kubernetes","level":"Middle","translations":{"uk":{"question":"Як безпечно працювати із secrets у CI/CD?","answer":"Secrets не зберігають у repository чи artifacts, видають jobs за принципом least privilege, маскують у logs і регулярно rotate. Pull requests із недовіреного коду не повинні автоматично отримувати production credentials. Короткоживуча federated identity часто безпечніша за довгоживучий token.","examples":["Deployment job отримує тимчасове cloud credential лише після approval, а test job не має production access."],"exercises":["Побудуйте permission matrix для lint, test, preview і production deploy jobs та знайдіть зайві права."]},"en":{"question":"How should secrets be handled safely in CI/CD?","answer":"Do not store secrets in repositories or artefacts; grant them to jobs under least privilege, mask them in logs, and rotate them regularly. Pull requests running untrusted code must not automatically receive production credentials. Short-lived federated identity is often safer than a long-lived token.","examples":["A deployment job receives temporary cloud credentials only after approval, while test jobs have no production access."],"exercises":["Build a permission matrix for lint, test, preview, and production deployment jobs, then remove unnecessary rights."]}}},{"id":"quality-gate-design","direction":"cicd-docker-kubernetes","level":"Middle","translations":{"uk":{"question":"Що робить quality gate корисним, а не формальним?","answer":"Gate блокує конкретний неприйнятний ризик і дає зрозумілий evidence: failed tests, critical vulnerability, порушений contract або policy. Threshold має owner, обґрунтування та процес винятку. Велика кількість нестабільних перевірок привчає команду ігнорувати червоний pipeline.","examples":["Gate блокує відому critical exploitable vulnerability, але informational finding лише потрапляє у звіт."],"exercises":["Для pipeline визначте blocking, warning і informational findings та процес тимчасового exception."]},"en":{"question":"What makes a quality gate useful instead of ceremonial?","answer":"A gate blocks a specific unacceptable risk and provides understandable evidence: failed tests, a critical vulnerability, a broken contract, or a policy violation. A threshold needs an owner, rationale, and exception process. Large numbers of unstable checks teach teams to ignore a red pipeline.","examples":["A gate blocks a known critical exploitable vulnerability, while an informational finding only appears in the report."],"exercises":["Classify pipeline findings as blocking, warning, or informational and define a temporary-exception process."]}}},{"id":"deployment-strategies","direction":"cicd-docker-kubernetes","level":"Senior","translations":{"uk":{"question":"Як вибирати між rolling, blue-green і canary deployment?","answer":"Вибір залежить від сумісності версій, state, вартості, blast radius і швидкості rollback:","answerPoints":["Rolling поступово замінює instances з невеликою додатковою інфраструктурою.","Blue-green тримає два environments і дає швидке перемикання.","Canary спрямовує частину трафіку на нову версію та потребує якісних metrics."],"examples":["Canary на 5% трафіку автоматично зупиняється при зростанні error rate і latency проти baseline."],"exercises":["Оберіть strategy для stateful API з database migration та опишіть критерії promotion і abort."]},"en":{"question":"How do you choose among rolling, blue-green, and canary deployment?","answer":"Choose based on version compatibility, state, cost, blast radius, and rollback speed:","answerPoints":["Rolling gradually replaces instances with little extra infrastructure.","Blue-green maintains two environments and enables fast switching.","Canary sends a traffic subset to the new version and requires strong metrics."],"examples":["A 5% canary automatically stops when error rate and latency increase relative to baseline."],"exercises":["Choose a strategy for a stateful API with a database migration and define promotion and abort criteria."]}}},{"id":"rollback-observability","direction":"cicd-docker-kubernetes","level":"Senior","translations":{"uk":{"question":"Чому успішний rollout не доводить успішний release?","answer":"Оркестратор може показати Healthy, хоча бізнесові помилки, повільні запити або неправильні дані вже шкодять користувачам. Потрібні technical і product signals, порівняння з baseline, traceability до version та перевірений rollback. Для destructive data change rollback коду може бути неможливим, тому потрібен roll-forward plan.","examples":["Pods ready, але conversion падає через помилку price calculation; business metric виявляє це раніше за CPU alert."],"exercises":["Складіть release dashboard із golden signals, business KPI, version marker і автоматичними abort conditions."]},"en":{"question":"Why does a successful rollout not prove a successful release?","answer":"An orchestrator may report Healthy while business errors, slow requests, or incorrect data already harm users. Use technical and product signals, compare against a baseline, trace results to a version, and test rollback. Destructive data changes may make code rollback impossible, requiring a roll-forward plan.","examples":["Pods are ready, but conversion drops because of a pricing defect; a business metric catches it before a CPU alert."],"exercises":["Design a release dashboard with golden signals, a business KPI, a version marker, and automatic abort conditions."]}}},{"id":"security-risk-cia","direction":"security-devsecops","level":"Junior","translations":{"uk":{"question":"Як confidentiality, integrity та availability допомагають аналізувати security risk?","answer":"CIA triad дає три базові види впливу: розкриття даних, несанкціонована зміна та недоступність. Ризик також враховує ймовірність, exposure і цінність активу. Одна вразливість може впливати на кілька властивостей, тому severity не визначають лише за технічним типом finding.","examples":["IDOR розкриває чужі дані, а можливість змінити їх додатково порушує integrity."],"exercises":["Оберіть три assets продукту й опишіть загрози confidentiality, integrity та availability для кожного."]},"en":{"question":"How do confidentiality, integrity, and availability support security-risk analysis?","answer":"The CIA triad provides three basic impact categories: data disclosure, unauthorised modification, and unavailability. Risk also considers likelihood, exposure, and asset value. One vulnerability may affect several properties, so severity should not be derived from the technical finding type alone.","examples":["An IDOR exposes another user’s data, while the ability to change it also violates integrity."],"exercises":["Choose three product assets and describe confidentiality, integrity, and availability threats for each."]}}},{"id":"xss-contextual-encoding","direction":"security-devsecops","level":"Junior","translations":{"uk":{"question":"Чому XSS захищають contextual output encoding, а не одним фільтром?","answer":"Небезпечні символи мають різне значення в HTML, attribute, URL, CSS і JavaScript contexts. Дані потрібно кодувати для конкретного output context, уникати небезпечних sinks і санітизувати дозволений HTML перевіреною library. Input validation корисна, але сама не зупиняє всі XSS-вектори.","examples":["Рядок, безпечний у текстовому HTML node, може бути небезпечним усередині JavaScript string або href."],"exercises":["Позначте source, transformation і sink для трьох user inputs та виберіть захист для кожного context."]},"en":{"question":"Why does XSS prevention require contextual output encoding instead of one filter?","answer":"Dangerous characters have different meanings in HTML, attribute, URL, CSS, and JavaScript contexts. Encode data for its specific output context, avoid unsafe sinks, and sanitise allowed HTML with a proven library. Input validation helps but cannot stop every XSS vector by itself.","examples":["A string safe in an HTML text node may be dangerous inside a JavaScript string or href."],"exercises":["Mark the source, transformation, and sink for three user inputs and choose protection for each context."]}}},{"id":"session-security","direction":"security-devsecops","level":"Middle","translations":{"uk":{"question":"Що перевіряти в authentication session крім успішного login?","answer":"Перевіряють session ID rotation після login і privilege change, expiry, logout invalidation, concurrent sessions, brute-force protection, reset flows і безпечні cookie attributes. Помилки часто живуть у переходах стану, а не у формі login. Sensitive action може вимагати re-authentication.","examples":["Викрадений pre-login session ID не має залишитися валідним після того, як користувач автентифікувався."],"exercises":["Побудуйте state model для login, MFA, refresh, logout і password reset та визначте негативні переходи."]},"en":{"question":"What should be tested in an authentication session beyond successful login?","answer":"Test session-ID rotation after login and privilege changes, expiry, logout invalidation, concurrent sessions, brute-force protection, reset flows, and secure cookie attributes. Defects often live in state transitions rather than the login form. Sensitive actions may require re-authentication.","examples":["A stolen pre-login session ID must not remain valid after the user authenticates."],"exercises":["Build a state model for login, MFA, refresh, logout, and password reset, then identify invalid transitions."]}}},{"id":"supply-chain-sbom","direction":"security-devsecops","level":"Middle","translations":{"uk":{"question":"Що дають SCA та SBOM у software supply chain?","answer":"SCA знаходить відомі ризики в dependencies, а SBOM інвентаризує компоненти й версії для traceability. Finding потребує triage: чи компонент reachable, exploitable, deployed і чи є compensating controls. Відсутність відомого CVE не доводить безпечність, а автоматичний upgrade теж може створити regression.","examples":["Critical CVE у build-only package може мати інший ризик, ніж reachable library у production request path."],"exercises":["Для dependency finding зберіть version, path, reachability, exploitability, fix і рішення з owner та deadline."]},"en":{"question":"What do SCA and an SBOM provide in a software supply chain?","answer":"SCA finds known risks in dependencies, while an SBOM inventories components and versions for traceability. A finding needs triage: is the component reachable, exploitable, deployed, and protected by compensating controls? No known CVE does not prove safety, and an automatic upgrade can also create regressions.","examples":["A critical CVE in a build-only package may carry different risk from a reachable library on the production request path."],"exercises":["For one dependency finding, record version, path, reachability, exploitability, fix, owner, and deadline."]}}},{"id":"threat-modeling-stride","direction":"security-devsecops","level":"Senior","translations":{"uk":{"question":"Як threat modeling перетворюється на перевірки?","answer":"Команда описує assets, actors, data flows, trust boundaries і можливі зловживання. STRIDE або attack trees допомагають не забути класи загроз, але не замінюють доменний аналіз. Кожна значуща загроза отримує mitigation, verification method, owner і залишковий ризик.","examples":["На межі public API → internal service загроза spoofing веде до перевірок token validation, audience та service identity."],"exercises":["Побудуйте data-flow diagram невеликого сервісу й перетворіть п’ять загроз на concrete security tests."]},"en":{"question":"How does threat modelling turn into concrete checks?","answer":"The team describes assets, actors, data flows, trust boundaries, and possible abuse. STRIDE or attack trees help cover threat classes but do not replace domain analysis. Every meaningful threat receives a mitigation, verification method, owner, and residual-risk decision.","examples":["At a public API → internal service boundary, a spoofing threat leads to tests of token validation, audience, and service identity."],"exercises":["Create a data-flow diagram for a small service and turn five threats into concrete security tests."]}}},{"id":"container-runtime-hardening","direction":"security-devsecops","level":"Senior","translations":{"uk":{"question":"Які controls зменшують blast radius контейнера?","answer":"Контейнер запускають non-root, із мінімальними Linux capabilities, read-only filesystem, resource limits, seccomp/AppArmor policy та обмеженою мережею. Image має бути мінімальним, відомого походження й просканованим, але isolation контейнера не дорівнює VM boundary. Runtime monitoring доповнює preventive controls.","examples":["Service не потребує shell і записує лише в окремий temporary volume; root filesystem залишається read-only."],"exercises":["Перевірте deployment manifest на privilege escalation, capabilities, secrets, network policy та resource limits."]},"en":{"question":"Which controls reduce a container’s blast radius?","answer":"Run containers as non-root with minimal Linux capabilities, a read-only filesystem, resource limits, seccomp or AppArmor policy, and restricted networking. Use minimal, traceable, scanned images, but remember that container isolation is not equivalent to a VM boundary. Runtime monitoring complements preventive controls.","examples":["A service needs no shell and writes only to a dedicated temporary volume while its root filesystem remains read-only."],"exercises":["Review a deployment manifest for privilege escalation, capabilities, secrets, network policy, and resource limits."]}}}]')},3761,(e,t,s)=>{t.exports=JSON.parse('[{"id":"system-functional-nonfunctional-requirements","direction":"system-design-cloud","level":"Junior","translations":{"uk":{"question":"Чому system design починається з functional і non-functional requirements?","answer":"Functional requirements визначають потрібну поведінку, а non-functional — цільові властивості: latency, throughput, availability, durability, security та cost. Без числових assumptions неможливо обґрунтовано вибрати storage, scaling чи consistency model. Архітектура є відповіддю на вимоги, а не каталогом модних сервісів.","examples":["Система має приймати 500 jobs за секунду, завершувати 95% до 30 секунд і не втрачати підтверджені jobs."],"exercises":["Для сервісу завантаження файлів сформулюйте три functional та п’ять вимірюваних non-functional requirements."]},"en":{"question":"Why does system design start with functional and non-functional requirements?","answer":"Functional requirements define required behaviour, while non-functional requirements define target properties such as latency, throughput, availability, durability, security, and cost. Without numerical assumptions, storage, scaling, or consistency choices cannot be justified. Architecture responds to requirements rather than showcasing fashionable services.","examples":["A system must accept 500 jobs per second, finish 95% within 30 seconds, and lose no acknowledged jobs."],"exercises":["For a file-upload service, define three functional and five measurable non-functional requirements."]}}},{"id":"horizontal-scaling-statelessness","direction":"system-design-cloud","level":"Junior","translations":{"uk":{"question":"Чому stateless service простіше масштабувати горизонтально?","answer":"Якщо instance не зберігає незамінний session state локально, будь-який healthy instance може обробити наступний request. Це спрощує load balancing, replacement і autoscaling. Стан не зникає — його переносять у shared storage, cache або token, де з’являються власні consistency та availability trade-offs.","examples":["Session зберігається у shared store, тому запити користувача можуть потрапляти на різні instances без sticky routing."],"exercises":["Знайдіть локальний state у монолітному сервісі й запропонуйте варіанти винесення з їхніми ризиками."]},"en":{"question":"Why is a stateless service easier to scale horizontally?","answer":"When an instance keeps no irreplaceable session state locally, any healthy instance can handle the next request. This simplifies load balancing, replacement, and autoscaling. State does not disappear—it moves to shared storage, a cache, or a token, introducing its own consistency and availability trade-offs.","examples":["A session lives in a shared store, so a user’s requests can reach different instances without sticky routing."],"exercises":["Identify local state in a monolithic service and propose ways to externalise it, including risks."]}}},{"id":"cache-tradeoffs","direction":"system-design-cloud","level":"Middle","translations":{"uk":{"question":"Які trade-offs додає cache до системи?","answer":"Cache зменшує latency та навантаження на source of truth, але створює invalidation, stampede, eviction і consistency problems. Потрібно визначити cache key, TTL, write policy, поведінку при miss і outage. Cache не має ставати прихованим єдиним джерелом критичних даних.","examples":["Після зміни ціни write-through оновлює cache, а короткий TTL обмежує наслідки пропущеної invalidation."],"exercises":["Для product catalog порівняйте cache-aside і write-through та спроєктуйте тест stale data і cache outage."]},"en":{"question":"Which trade-offs does a cache add to a system?","answer":"A cache reduces latency and load on the source of truth but introduces invalidation, stampede, eviction, and consistency problems. Define cache keys, TTL, write policy, miss behaviour, and outage behaviour. A cache should not silently become the only source of critical data.","examples":["After a price change, write-through updates the cache, while a short TTL limits the impact of missed invalidation."],"exercises":["For a product catalogue, compare cache-aside with write-through and design stale-data and cache-outage tests."]}}},{"id":"distributed-consistency","direction":"system-design-cloud","level":"Middle","translations":{"uk":{"question":"Як вибирати consistency model у distributed system?","answer":"Вибір залежить від бізнесового інваріанта й допустимого вікна розходження. Strong consistency спрощує деякі рішення, але може збільшити latency або зменшити availability під час partition. Eventual consistency потребує idempotency, conflict handling, reconciliation та зрозумілої UX-поведінки.","examples":["Лічильник переглядів може збігатися згодом, але подвійне списання грошей порушує критичний інваріант."],"exercises":["Класифікуйте п’ять даних продукту за допустимою stale window і поясніть consistency choice."]},"en":{"question":"How should a consistency model be chosen in a distributed system?","answer":"The choice depends on the business invariant and the acceptable divergence window. Strong consistency simplifies some decisions but may increase latency or reduce availability during a partition. Eventual consistency requires idempotency, conflict handling, reconciliation, and understandable user experience.","examples":["A view counter may converge later, while charging money twice violates a critical invariant."],"exercises":["Classify five product data types by acceptable staleness window and justify the consistency choice."]}}},{"id":"high-availability-disaster-recovery","direction":"system-design-cloud","level":"Senior","translations":{"uk":{"question":"Чим high availability відрізняється від disaster recovery?","answer":"High availability мінімізує interruption при звичайних component failures через redundancy та failover. Disaster recovery відновлює систему після масштабної втрати region, даних або control plane. Репліка не замінює backup, якщо помилкове видалення реплікується всюди; recovery plan потрібно регулярно випробовувати.","examples":["Multi-zone deployment переживає падіння node, а відновлення з immutable backup покриває знищення primary database."],"exercises":["Спроєктуйте game day для region outage: detection, failover, data validation, communication і return to normal."]},"en":{"question":"How does high availability differ from disaster recovery?","answer":"High availability minimises interruption during ordinary component failures through redundancy and failover. Disaster recovery restores the system after large-scale loss of a region, data, or control plane. A replica does not replace a backup when accidental deletion replicates everywhere; recovery plans require regular exercises.","examples":["A multi-zone deployment survives a node failure, while restoration from an immutable backup covers destruction of the primary database."],"exercises":["Design a game day for a region outage: detection, failover, data validation, communication, and return to normal."]}}},{"id":"capacity-cost-model","direction":"system-design-cloud","level":"Senior","translations":{"uk":{"question":"Як capacity model пов’язує performance і cloud cost?","answer":"Модель використовує arrival rate, concurrency, latency, payload size, storage growth і headroom для оцінки ресурсів. Autoscaling реагує із затримкою й не виправляє bottleneck у database або downstream dependency. Вартість рахують на одиницю корисної роботи, включаючи idle capacity, network egress і observability.","examples":["За Little’s Law 100 requests/s із середньою latency 0.2 s дають приблизно 20 одночасних requests без запасу."],"exercises":["Оцініть compute, storage та egress для трьох навантажень і визначте сигнал autoscaling та safety margin."]},"en":{"question":"How does a capacity model connect performance and cloud cost?","answer":"A model uses arrival rate, concurrency, latency, payload size, storage growth, and headroom to estimate resources. Autoscaling reacts with delay and cannot fix a bottleneck in a database or downstream dependency. Calculate cost per useful unit of work, including idle capacity, network egress, and observability.","examples":["By Little’s Law, 100 requests per second at 0.2-second average latency imply about 20 concurrent requests before headroom."],"exercises":["Estimate compute, storage, and egress for three load levels, then define an autoscaling signal and safety margin."]}}},{"id":"llm-tokens-context-window","direction":"ai-llm-rag-agents","level":"Junior","translations":{"uk":{"question":"Що таке tokens і context window в LLM-системі?","answer":"Модель обробляє текст як tokens, а context window обмежує сумарний обсяг instructions, history, retrieved data та output. Більший контекст не гарантує кращої відповіді: нерелевантний текст збільшує cost, latency і ризик втрати важливого сигналу. Контекст потрібно відбирати та структурувати.","examples":["Довгий log dump може витіснити acceptance criteria, хоча формально все помістилося у window."],"exercises":["Розділіть prompt budget між instructions, task data, retrieved evidence та output і поясніть пріоритети."]},"en":{"question":"What are tokens and a context window in an LLM system?","answer":"A model processes text as tokens, while the context window limits the combined size of instructions, history, retrieved data, and output. More context does not guarantee a better answer: irrelevant text increases cost, latency, and the chance of losing important signals. Select and structure context deliberately.","examples":["A long log dump can obscure acceptance criteria even when everything technically fits in the window."],"exercises":["Allocate a prompt budget among instructions, task data, retrieved evidence, and output, explaining priorities."]}}},{"id":"embeddings-retrieval","direction":"ai-llm-rag-agents","level":"Junior","translations":{"uk":{"question":"Що embeddings роблять у retrieval system?","answer":"Embedding перетворює текст на vector representation, де близькість приблизно відображає семантичну схожість. Retrieval знаходить кандидати, але similarity не гарантує фактичну релевантність, актуальність чи дозвіл доступу. Metadata filters, lexical search і reranking часто доповнюють vector search.","examples":["Запит про password reset може знайти семантично близьку, але застарілу інструкцію; filter за version відсіює її."],"exercises":["Створіть п’ять queries із expected documents і визначте failure cases для similarity-only retrieval."]},"en":{"question":"What do embeddings do in a retrieval system?","answer":"An embedding maps text to a vector representation where proximity roughly reflects semantic similarity. Retrieval finds candidates, but similarity does not guarantee factual relevance, freshness, or access permission. Metadata filters, lexical search, and reranking often complement vector search.","examples":["A password-reset query may retrieve a semantically similar but obsolete guide; a version filter removes it."],"exercises":["Create five queries with expected documents and identify failure cases for similarity-only retrieval."]}}},{"id":"rag-chunking-reranking","direction":"ai-llm-rag-agents","level":"Middle","translations":{"uk":{"question":"Як chunking і reranking впливають на RAG quality?","answer":"Chunk має зберігати завершену думку й достатній локальний контекст, але не змішувати забагато тем. Retrieval швидко відбирає candidates, reranker точніше впорядковує їх відносно query. Якість вимірюють окремо на retrieval stage, бо генератор не може надійно виправити відсутній evidence.","examples":["Chunk за section boundary зберігає правило разом із винятками, тоді як фіксований розріз може їх розділити."],"exercises":["Порівняйте два chunking strategies на десяти queries за recall@k і якістю top-ranked context."]},"en":{"question":"How do chunking and reranking affect RAG quality?","answer":"A chunk should preserve a complete idea and enough local context without mixing too many topics. Retrieval selects candidates quickly, while a reranker orders them more precisely for the query. Measure retrieval quality separately because a generator cannot reliably repair missing evidence.","examples":["A section-boundary chunk keeps a rule with its exceptions, while a fixed-size split may separate them."],"exercises":["Compare two chunking strategies on ten queries using recall@k and top-ranked context quality."]}}},{"id":"structured-output-tool-calls","direction":"ai-llm-rag-agents","level":"Middle","translations":{"uk":{"question":"Чим structured output відрізняється від виконання tool call?","answer":"Structured output обмежує форму згенерованих даних schema, але не доводить істинність значень. Tool call — пропозиція моделі викликати capability з arguments; фактичне виконання контролює application. Перед side effect потрібні validation, authorization, idempotency та, для ризикових дій, human approval.","examples":["Валідний JSON із deleteUserId все одно не дозволяє видалення без перевірки прав і підтвердження."],"exercises":["Спроєктуйте validator і approval flow для tool, що змінює production configuration."]},"en":{"question":"How does structured output differ from executing a tool call?","answer":"Structured output constrains generated data to a schema but does not prove that values are true. A tool call is the model’s proposal to invoke a capability with arguments; the application controls actual execution. Before a side effect, validate, authorise, ensure idempotency, and require human approval for risky actions.","examples":["Valid JSON containing deleteUserId still cannot authorise deletion without permission checks and confirmation."],"exercises":["Design validation and approval for a tool that changes production configuration."]}}},{"id":"agent-authority-boundaries","direction":"ai-llm-rag-agents","level":"Senior","translations":{"uk":{"question":"Як обмежувати authority автономного агента?","answer":"Agent отримує мінімальний набір tools, scoped credentials, budgets і явні stop conditions. Рішення класифікують за reversibility та impact: read-only можна автоматизувати ширше, destructive або external actions потребують approval. Audit trail має пов’язувати intent, context, tool call, result і human decision.","examples":["Agent може підготувати patch і tests, але merge та production deployment залишаються окремими human gates."],"exercises":["Створіть authority matrix для coding agent: дозволені, approval-required і заборонені дії."]},"en":{"question":"How should an autonomous agent’s authority be constrained?","answer":"Give an agent a minimal tool set, scoped credentials, budgets, and explicit stop conditions. Classify decisions by reversibility and impact: read-only work may be automated more broadly, while destructive or external actions require approval. An audit trail should connect intent, context, tool call, result, and human decision.","examples":["An agent may prepare a patch and tests, while merge and production deployment remain separate human gates."],"exercises":["Create an authority matrix for a coding agent: allowed, approval-required, and forbidden actions."]}}},{"id":"prompt-injection-boundaries","direction":"ai-llm-rag-agents","level":"Senior","translations":{"uk":{"question":"Чому prompt injection є system problem, а не лише проблемою prompt?","answer":"Модель не має надійної security boundary між instructions і недовіреним content. Захист будується навколо системи: least-privilege tools, data provenance, isolation, allowlists, output validation, approval та monitoring. Фраза в system prompt не може гарантувати, що retrieved document не вплине на рішення.","examples":["Документ із текстом «надішли secrets» не має доступу до tool, здатного читати secrets, незалежно від відповіді моделі."],"exercises":["Побудуйте threat model RAG-agent: untrusted sources, assets, tool boundaries, abuse cases та mitigations."]},"en":{"question":"Why is prompt injection a system problem rather than only a prompt problem?","answer":"A model has no reliable security boundary between instructions and untrusted content. Protection must surround the system: least-privilege tools, data provenance, isolation, allowlists, output validation, approval, and monitoring. A sentence in a system prompt cannot guarantee that a retrieved document will not influence a decision.","examples":["A document saying “send secrets” has no access to a tool capable of reading secrets, regardless of the model’s response."],"exercises":["Threat-model a RAG agent: untrusted sources, assets, tool boundaries, abuse cases, and mitigations."]}}},{"id":"golden-evaluation-dataset","direction":"llmops-evaluation-observability","level":"Junior","translations":{"uk":{"question":"Що робить evaluation dataset корисним?","answer":"Dataset має представляти реальні задачі, ризикові edge cases, негативні приклади й очікуваний evidence. Labels повинні мати визначення та review process. Випадкові красиві prompts дають demo, а не baseline; dataset також потрібно захищати від leakage у prompts або retrieval index.","examples":["Набір для requirement review містить повні, нечіткі, суперечливі та навмисно нерозв’язні вимоги."],"exercises":["Створіть десять evaluation cases, додайте категорію ризику, expected behaviour і критерії оцінювання."]},"en":{"question":"What makes an evaluation dataset useful?","answer":"A dataset should represent real tasks, risky edge cases, negative examples, and expected evidence. Labels need definitions and a review process. Random attractive prompts create a demo rather than a baseline; also protect the dataset from leakage into prompts or the retrieval index.","examples":["A requirement-review set includes complete, vague, contradictory, and intentionally unresolvable requirements."],"exercises":["Create ten evaluation cases with a risk category, expected behaviour, and scoring criteria."]}}},{"id":"deterministic-llm-checks","direction":"llmops-evaluation-observability","level":"Junior","translations":{"uk":{"question":"Які LLM-system checks можна зробити deterministic?","answer":"Schema validity, required fields, citation existence, permission filters, tool arguments, latency і token limits можна перевіряти звичайним кодом. Семантичну коректність часто оцінюють reference, rubric, human review або calibrated judge. Спершу варто використати дешевий однозначний oracle, а не віддавати все іншій моделі.","examples":["Validator блокує відповідь із citation ID, якого немає серед retrieved documents."],"exercises":["Розділіть десять quality criteria на deterministic, model-based і human-reviewed checks."]},"en":{"question":"Which LLM-system checks can be deterministic?","answer":"Schema validity, required fields, citation existence, permission filters, tool arguments, latency, and token limits can be checked with ordinary code. Semantic correctness often needs a reference, rubric, human review, or calibrated judge. Use a cheap, unambiguous oracle before delegating everything to another model.","examples":["A validator rejects an answer containing a citation ID that is absent from retrieved documents."],"exercises":["Classify ten quality criteria as deterministic, model-based, or human-reviewed checks."]}}},{"id":"retrieval-precision-recall","direction":"llmops-evaluation-observability","level":"Middle","translations":{"uk":{"question":"Як precision і recall застосовуються до retrieval evaluation?","answer":"Recall показує, яку частку потрібних документів система знайшла; precision — яка частка знайдених справді релевантна. Збільшення top-k часто підвищує recall, але додає шум і cost. Метрики рахують на labeled queries та доповнюють rank-aware показниками, якщо позиція результату важлива.","examples":["Пошук знаходить усі три потрібні документи серед двадцяти: recall високий, але precision низький."],"exercises":["Для п’яти queries вручну позначте relevance й порахуйте precision@k та recall@k для двох retrievers."]},"en":{"question":"How do precision and recall apply to retrieval evaluation?","answer":"Recall measures how much of the required material the system found; precision measures how much of the retrieved material is actually relevant. Increasing top-k often raises recall but adds noise and cost. Calculate metrics on labelled queries and add rank-aware measures when result position matters.","examples":["Search finds all three required documents among twenty results: recall is high, but precision is low."],"exercises":["Label relevance for five queries and calculate precision@k and recall@k for two retrievers."]}}},{"id":"llm-system-versioning","direction":"llmops-evaluation-observability","level":"Middle","translations":{"uk":{"question":"Що потрібно версіонувати для відтворюваності LLM-system result?","answer":"Фіксують model і parameters, system/developer prompts, tool schemas, application code, retrieval corpus, chunker, embedding model, index, reranker та evaluation dataset. Provider model alias може змінитися без code commit, тому run metadata має зберігати доступний concrete identifier і час.","examples":["Однаковий prompt дав інший результат після оновлення index; trace показує різні retrieved chunks і версію corpus."],"exercises":["Створіть run manifest, достатній для порівняння двох releases та пояснення зміни quality metric."]},"en":{"question":"What must be versioned to reproduce an LLM-system result?","answer":"Record the model and parameters, system and developer prompts, tool schemas, application code, retrieval corpus, chunker, embedding model, index, reranker, and evaluation dataset. A provider model alias may change without a code commit, so run metadata should keep the available concrete identifier and timestamp.","examples":["The same prompt changes after an index update; the trace reveals different retrieved chunks and corpus versions."],"exercises":["Create a run manifest sufficient to compare two releases and explain a quality-metric change."]}}},{"id":"llm-regression-gates","direction":"llmops-evaluation-observability","level":"Senior","translations":{"uk":{"question":"Як будувати regression gate для недетермінованої LLM-системи?","answer":"Gate використовує повторні runs, статистично осмислений baseline, сегментацію за ризиком і окремі hard constraints. Critical safety або authorization failure може блокувати одразу, а aggregate quality потребує tolerance та confidence interval. Результати judge калібрують проти human labels і регулярно перевіряють drift.","examples":["Release блокується за будь-який unauthorized tool call, але answer-quality score порівнюється з baseline у межах узгодженої похибки."],"exercises":["Спроєктуйте gate з hard failures, aggregate metrics, sample size, threshold owner і manual override process."]},"en":{"question":"How can a regression gate be built for a nondeterministic LLM system?","answer":"Use repeated runs, a statistically meaningful baseline, risk segmentation, and separate hard constraints. A critical safety or authorisation failure may block immediately, while aggregate quality needs tolerance and a confidence interval. Calibrate judge results against human labels and monitor drift.","examples":["Any unauthorised tool call blocks release, while answer-quality score is compared with baseline within an agreed margin."],"exercises":["Design a gate with hard failures, aggregate metrics, sample size, threshold owner, and manual override process."]}}},{"id":"llm-cost-latency-reliability","direction":"llmops-evaluation-observability","level":"Senior","translations":{"uk":{"question":"Як разом оптимізувати quality, latency, cost і reliability?","answer":"Це multi-objective trade-off: більша модель або довший context можуть підвищити якість, але збільшити latency та cost. Вимірюють end-to-end distribution, token usage, retries, failure rate і quality за сегментами. Routing, caching і fallback корисні лише якщо не порушують freshness, privacy та correctness.","examples":["Прості classification requests ідуть до меншої моделі, а складні cases — до сильнішої після confidence check."],"exercises":["Побудуйте scorecard двох моделей за quality, p95 latency, cost per task і failure rate та визначте routing rule."]},"en":{"question":"How can quality, latency, cost, and reliability be optimised together?","answer":"This is a multi-objective trade-off: a larger model or longer context may improve quality while increasing latency and cost. Measure end-to-end distributions, token use, retries, failure rate, and quality by segment. Routing, caching, and fallback help only when they preserve freshness, privacy, and correctness.","examples":["Simple classification requests use a smaller model, while difficult cases route to a stronger one after a confidence check."],"exercises":["Build a scorecard for two models using quality, p95 latency, cost per task, and failure rate, then define a routing rule."]}}}]')},3118,e=>{"use strict";var t=e.i(7150),s=e.i(4555),a=e.i(2400),i=e.i(2365),n=e.i(8403),r=e.i(3761);t.default;let o={Junior:0,Middle:1,Senior:2},c=[...s.default,...a.default,...i.default,...n.default,...r.default];e.s(["getDirectionTranslation",0,function(e,t){return e.translations[t]??null},"getKnowledgeMaterials",0,function(e){return c.filter(t=>t.direction===e).sort((e,t)=>(e.level?o[e.level]:3)-(t.level?o[t.level]:3))},"getMaterialTranslation",0,function(e,t){return e.translations[t]??null}])}]);